NAME = 'TpiKJPB: King Jems Pisin Baibel'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: '¶ Stat bilong gutnius bilong Jisas Kraist, Pikinini Man bilong God.',
        2: 'Olsem rait i stap pinis long ol profet, Lukim, Mi salim mausman bilong Mi i go paslain long pes bilong Yu, husat bai redim rot bilong Yu long ai bilong Yu.',
        3: 'Nek bilong wanpela i singaut long ples i no gat man, Yupela redim rot bilong Bikpela, mekim ol liklik rot bilong Em stretpela.',
        4: 'Jon i bin givim baptais long ples i no gat man, na autim baptais bilong tanim bel bilong lusim ol sin.',
        5: 'Na i gat i go ausait i go long em olgeta bilong hap graun bilong Judia, na ol bilong Jerusalem, na ol olgeta i kisim baptais long em long wara Jordan, na autim ol sin bilong ol.',
        6: 'Na Jon i werim klos long gras bilong kemel, na long wanpela bikpela let bilong skin bilong animal raun nabaut long ol namel bilong bel bilong em. Na em i bin kaikai ol lokas na wail hani.',
        7: 'Na em i autim tok, i spik, I gat i kam bihain long mi wanpela i strongpela moa long mi, string bilong su bilong husat mi no gat namba inap long lindaun na lusim.',
        8: 'Em i tru long mi bin givim baptais long yupela wantaim wara. Tasol Em bai givim baptais long yupela wantaim Holi Spirit.',
        9: '¶ Na em i kamap olsem long ol dispela de, long Jisas i lusim Nasaret bilong Galili i kam, na kisim baptais long Jon long Jordan.',
        10: 'Na kwiktaim taim Em i kam antap ausait long wara, em i lukim ol heven i op, na Spirit olsem wanpela balus i kam daun antap long Em.',
        11: 'Na i gat wanpela nek i kam long heven, i spik, Yu stap Pikinini Man i stap klostu tru long bel bilong Mi, long husat Mi gat gutpela amamas tru.',
        12: 'Na wantu Spirit i ranim Em i go long ples i no gat man.',
        13: 'Na Em i stap long dispela hap long ples i no gat man 40 de, na Seten i traim Em. Na Em i stap wantaim ol wail animal. Na ol ensel i kam na wokim wok long Em.',
        14: '¶ Nau bihain long ol i putim Jon long kalabus, Jisas i kam long Galili, na autim gutnius bilong kingdom bilong God,',
        15: 'Na tok, Taim i kamap pinis, na kingdom bilong God i stap klostu. Yupela tanim bel, na bilipim gutnius.',
        16: 'Nau taim Em i wokabaut klostu long biksi Galili, Em i lukim Saimon na brata bilong em Andru taim ol i tromoi wanpela umben long biksi. Long wanem, ol i ol man bilong painim pis.',
        17: 'Na Jisas i tokim tupela, Yutupela kam bihainim Mi, na Mi bai mekim yutupela long kamap ol man bilong painim ol man.',
        18: 'Na kwiktaim ol i givim baksait long ol umben bilong ol, na bihainim Em.',
        19: 'Na taim Em i bin go liklik moa long dispela ples, Em i lukim Jems, pikinini man bilong Sebedi, na brata bilong em Jon, husat tu i stap long sip na stretim ol umben bilong ol.',
        20: 'Na kwiktaim Em i singautim ol. Na ol i lusim papa bilong ol Sebedi long sip wantaim ol wokboi em i baim, na ol i go bihainim Em.',
        21: 'Na ol i go insait long Kaperneam. Na kwiktaim long de sabat Em i go insait long sinagog, na skulim ol manmeri.',
        22: 'Na ol i kirap nogut long skul bilong Em. Long wanem, Em i skulim ol olsem wanpela husat i gat namba bilong bosim, na i no olsem ol man bilong rait.',
        23: '¶ Na i gat long sinagog bilong ol wanpela man wantaim wanpela spirit i no klin. Na em i singaut,',
        24: 'I spik, Larim mipela i stap. Mipela i gat wanem wok wantaim Yu, Yu Jisas bilong Nasaret? Ating Yu kam bilong bagarapim mipela olgeta, a? Mi save long Yu long Yu stap husat, Man Holi bilong God.',
        25: 'Na Jisas i hatim em, i spik, Pasim maus bilong yu, na kam ausait long em.',
        26: 'Na taim dispela spirit i no klin i bin brukim em, na singaut wantaim bikpela nek, em i kam ausait long em.',
        27: 'Na ol olgeta i kirap nogut tru, inap olsem long ol i gat askim namel long ol yet, i spik, Dispela em i wanem samting? Dispela em i wanem nupela skul? Long wanem, wantaim namba bilong bosim Em i tok strong, yes, long ol spirit i no klin, na ol i bihainim tok bilong Em.',
        28: 'Na wantu biknem tru bilong Em i go nabaut ausait namel long olgeta hap graun raun nabaut long Galili.',
        29: '¶ Na wantu, taim ol i kam ausait long sinagog, ol i go insait long haus bilong Saimon na Andru, wantaim Jems na Jon.',
        30: 'Tasol mama bilong meri bilong Saimon i sik i slip wantaim skinhat, na kwiktaim ol i tokim Em long meri.',
        31: 'Na Em i kam na kisim em long han, na litimapim em. Na wantu skinhat i lusim em, na em i wokim wok long ol.',
        32: 'Na long apinun tru, taim san i bin go daun, ol i bringim long Em olgeta husat i gat ol sik nogut, na ol husat ol spirit nogut i holimpas ol.',
        33: 'Na olgeta dispela biktaun i bung wantaim long dua.',
        34: 'Na Em i oraitim planti husat i sik long ol kain kain sik nogut, na rausim i go planti spirit nogut. Na Em i no larim ol spirit nogut long toktok, bilong wanem, ol i save long Em.',
        35: 'Na long moningtaim, taim Em i kirap longpela taim bipo san i kam antap, Em i go ausait, na lusim dispela hap i go long wanpela ples i no gat man, na long dispela hap Em i beten.',
        36: 'Na Saimon na ol husat i stap wantaim Em i bihainim Em.',
        37: 'Na taim ol i bin lukim Em pinis, ol i tokim Em, Olgeta man i painim Yu.',
        38: 'Na Em i tokim ol, Yumi go long ol taun i klostu stret, inap long Mi ken autim tok long ol dispela hap tu. Long wanem, olsem tasol Mi kam ausait.',
        39: 'Na Em i autim tok long ol sinagog bilong ol namel long olgeta hap bilong Galili, na rausim i go ol spirit nogut.',
        40: '¶ Na i gat wanpela lepraman i kam long Em, na askim Em long daun pasin, na brukim skru long Em, na tokim Em, Sapos Yu gat laik, Yu ken mekim mi klin.',
        41: 'Na Jisas, taim pasin sori i muvim Em, i putim han bilong Em i go ausait, na tasim em, na tokim em, Mi gat laik. Yu stap klin.',
        42: 'Na long taim stret long Em i bin toktok, wantu dispela sik lepra i lusim em, na em i kamap klin.',
        43: 'Na Em i givim tok long em stret, na wantu Em i salim em i go.',
        44: 'Na Em i tokim em, Yu lukluk gut long yu no tokim wanpela samting long wanpela man. Tasol go long rot bilong yu, soim yu yet long pris, na wokim ofa bilong klinim bilong yu long ol dispela samting, dispela Moses i tok strong, bilong wanpela testimoni i go long ol.',
        45: 'Tasol em i go ausait, na stat long mekim dispela i kamap ples klia planti, na bilong tokaut long olgeta long dispela samting, inap olsem long Jisas i no inap go ples klia moa insait long dispela biktaun, tasol Em i stap ausait long ol ples i no gat man. Na ol i kam long Em long olgeta wan wan namba foa hap.',
    },
    2: {
        1: '¶ Na gen Em i go insait long Kaperneam bihain long sampela de. Na stori i ran long Em i stap insait long dispela haus.',
        2: 'Na kwiktaim planti i bung wantaim, inap olsem long i no gat spes long kisim ol, nogat, i no olsem tu nabaut long dua. Na Em i autim tok bilong God long ol.',
        3: 'Na ol i kam long Em, na bringim wanpela man i sik long sik palsi, husat fopela i karim.',
        4: 'Na taim ol i no inap long kam klostu long Em, long wanem, ol man i pas pas tumas, ol i rausim hap bilong rup we Em i stap. Na taim ol i bin brukim dispela, ol i lusim bet i go daun we dispela man i sik long sik palsi i slip long en.',
        5: 'Taim Jisas i lukim bilip tru bilong ol, Em i tokim man i sik long sik palsi, Pikinini man, Mi lusim ol sin bilong yu.',
        6: 'Tasol i gat long dispela hap sampela bilong ol man bilong rait i sindaun, na ol i wok long stretim tok insait long ol bel bilong ol,',
        7: 'Bilong wanem dispela Man i toktok long ol kain tok bilas olsem? Husat arapela i ken lusim ol sin, God wanpela tasol?',
        8: 'Na wantu taim Jisas i kisim save insait long spirit bilong Em long ol i wok long stretim tok olsem insait long ol yet, Em i tokim ol, Bilong wanem yupela i wok long stretim tok long ol dispela samting insait long ol bel bilong yupela?',
        9: 'Wanem em i isi moa long tokim man i sik long sik palsi, Mi lusim ol sin bilong yu, o long tok, Kirap, na kisim bet bilong yu i go antap, na wokabaut?',
        10: 'Tasol inap long yupela i ken save long Pikinini Man bilong man i gat pawa long dispela graun long lusim ol sin, (Em i tokim man i sik long sik palsi,)',
        11: 'Mi tokim yu, Kirap, na kisim bet bilong yu i go antap, na go long rot bilong yu i go insait long haus bilong yu.',
        12: 'Na wantu em i kirap, kisim bet i go antap, na go ausait long ai bilong ol olgeta. Inap olsem long ol olgeta i kirap nogut tru, na givim glori long God, i spik, Mipela i no bin lukim dispela long dispela kain pasin.',
        13: '¶ Na Em i go ausait gen klostu long nambis bilong biksi. Na olgeta bikpela lain tru i go long Em, na Em i skulim ol.',
        14: 'Na taim Em i wokabaut klostu, Em i lukim Livai, pikinini man bilong Alifias, i sindaun long kisim kastam mani, na Em i tokim em, Bihainim Mi. Na em i kirap na bihainim Em.',
        15: 'Na em i kamap olsem, long, taim Jisas i sindaun long kaikai long haus bilong em, planti man bilong kisim takis na ol sinman i sindaun tu wantaim, wantaim Jisas na ol disaipel bilong Em. Long wanem, i gat planti, na ol i bihainim Em.',
        16: 'Na taim ol man bilong rait na ol Farisi i lukim Em i kaikai wantaim ol man bilong kisim takis na ol sinman, ol i tokim ol disaipel bilong Em, Em i olsem wanem long Em i kaikai na dring wantaim ol man bilong kisim takis na ol sinman?',
        17: 'Taim Jisas i harim dispela, Em i tokim ol, Ol husat i orait olgeta i no gat nid long dokta, tasol ol husat i sik. Mi no kam long singautim ol stretpela man, tasol ol sinman bilong tanim bel.',
        18: '¶ Na ol disaipel bilong Jon na bilong ol Farisi i tambuim kaikai. Na ol i kam na tokim Em, Bilong wanem ol disaipel bilong Jon na bilong ol Farisi i tambuim kaikai, tasol ol disaipel bilong Yu i no tambuim kaikai?',
        19: 'Na Jisas i tokim ol, Ol pikinini bilong rum bilong meri i laik marit i ken tambuim kaikai, taim man i laik marit i stap wantaim ol? Taim ol i gat man i laik marit i stap yet wantaim ol, ol i no inap tambuim kaikai.',
        20: 'Tasol ol de bai kam, taim ol bai kisim man i laik marit i lusim ol i go, na nau bai ol i tambuim kaikai long ol dispela de.',
        21: 'I no gat man tu i samapim wanpela hap bilong nupela laplap antap long wanpela olpela klos. Nogut dispela nupela hap i pulimapim dispela bai tekewe long olpela, na mekim bruk i go nogut moa.',
        22: 'Na i no gat man i putim nupela wain insait long ol olpela skin meme. Nogut dispela nupela wain bai brukim ol skin meme, na wain bai kapsait, na ol skin meme bai bagarap. Tasol ol i mas putim nupela wain insait long ol nupela skin meme.',
        23: 'Na em i kamap olsem, long Em i go namel long ol bikpela gaden wit samting long de sabat. Na ol disaipel bilong Em i stat, taim ol i go, bilong kamautim ol ia bilong wit samting.',
        24: 'Na ol Farisi i tokim Em, Lukim, bilong wanem ol i mekim long de sabat dispela samting i no orait long lo?',
        25: 'Na Em i tokim ol, Ating i yes long yupela i bin ritim wanem samting Devit i mekim, taim em i gat nid, na em i hangre, em, na ol husat i stap wantaim em?',
        26: 'Long em i go insait long haus bilong God olsem wanem long ol de bilong hetpris Abaiatar, na em i bin kaikai dispela bret bilong soim, dispela i no orait long lo long narapela i ken kaikai, long ol pris tasol, na long em i givim tu long ol husat i stap wantaim em?',
        27: 'Na Em i tokim ol, God i wokim sabat bilong helpim man, na i no long man i ken helpim sabat.',
        28: 'Olsem na Pikinini Man bilong man em i Bikpela tu bilong sabat.',
    },
    3: {
        1: '¶ Na Em i go insait gen long sinagog. Na i gat wanpela man long dispela hap husat i gat wanpela han i drai.',
        2: 'Na ol i was long Em, long Em bai oraitim em long de sabat o nogat, inap long ol i ken sutim tok long Em.',
        3: 'Na Em i tokim dispela man husat i gat han i drai, Sanap ausait.',
        4: 'Na Em i tokim ol, Em i orait long lo long mekim gutpela long ol de sabat, ol long mekim nogut, long kisim bek laip, o long kilim? Tasol ol i pasim ol maus bilong ol.',
        5: 'Na taim Em i bin lukluk raun nabaut long ol wantaim kros, taim Em i pilim bel hevi long ol bel bilong ol i hat tru, Em i tokim dispela man, Stretim han bilong yu i go ausait. Na em i stretim han i go ausait. Na han bilong em i kamap orait gen olsem arapela.',
        6: 'Na ol Farisi i go ausait, na kwiktaim ol i kisim tok helpim wantaim ol lain bilong Herot i birua long Em, long ol i ken bagarapim Em olgeta olsem wanem.',
        7: 'Tasol Jisas i surikim Em Yet i go bek wantaim ol disaipel bilong Em i go long biksi. Na wanpela traipela lain tru i kam long Galili i bihainim Em, na i kam long Judia,',
        8: 'Na i kam long Jerusalem, na i kam long Idumia, na i kam long hapsait long Jordan. Na ol nabaut long Tair na Saidon, wanpela traipela lain tru, taim ol i bin harim wanem ol bikpela samting Em i mekim, ol i kam long Em.',
        9: 'Na Em i tokim ol disaipel bilong Em, long wanpela liklik sip i mas wetim Em, bilong wanem, dispela bikpela lain tru i stap, nogut ol i ken pas klostu strong long Em.',
        10: 'Long wanem, Em i bin oraitim planti. Inap olsem long ol i bin pas pas tumas long Em bilong tasim Em, hamas bilong ol i gat ol sik nogut.',
        11: 'Na ol spirit i no klin, taim ol i lukim Em, i pundaun long ai bilong Em, na singaut, i spik, Yu stap Pikinini Man bilong God.',
        12: 'Na Em i givim tok long ol stret long ol i no ken mekim ol man long save long Em.',
        13: '¶ Na Em i go antap long wanpela maunten, na singautim i kam long Em husat Em i laik. Na ol i kam long Em.',
        14: 'Na Em i makim twelpela, inap long ol i ken stap wantaim Em, na inap long Em i ken salim ol i go ausait bilong autim tok,',
        15: 'Na bilong ol i ken gat pawa bilong oraitim ol sik, na bilong rausim i go ol spirit nogut.',
        16: 'Na Saimon Em i givim narapela nem Pita.',
        17: 'Na Jems, pikinini man bilong Sebedi, na Jon, brata bilong Jems. Na Em i givim narapela nem Boanerjes long ol, dispela em i olsem, Ol pikinini man bilong klaut i pairap.',
        18: 'Na Andru, na Filip, na Bartolomyu, na Matyu, na Tomas, na Jems, pikinini man bilong Alifias, na Tadias, na man Kenan Saimon,',
        19: 'Na Judas Iskariot, husat tu i bin putim Em long han bilong birua. Na ol i go insait long wanpela haus.',
        20: 'Na dispela bikpela lain tru i kam bung wantaim gen, inap long ol i no inap mekim samting olsem ol i ken kaikai bret.',
        21: 'Na taim ol pren bilong Em i harim stori long dispela, ol i go ausait bilong holimpas Em. Long wanem, ol i tok, Em i longlong olgeta.',
        22: '¶ Na ol man bilong rait husat i kam daun long Jerusalem i tok, Em i gat Bielsebap, na long hetman bilong ol spirit nogut Em i rausim ol spirit nogut.',
        23: 'Na Em i singautim ol i kam long Em, na tokim ol long ol tok piksa, Seten i ken rausim Seten i go olsem wanem?',
        24: 'Na sapos wanpela kingdom i bruk i birua long em yet, dispela kingdom i no inap sanap.',
        25: 'Na sapos wanpela hauslain i bruk i birua long em yet, dispela hauslain i no inap sanap.',
        26: 'Na sapos Seten i kirap na birua long em yet, na stap bruk, em i no inap sanap, tasol em i gat wanpela pinis.',
        27: 'I no gat man i ken go insait long haus bilong strongpela man, na kisim ol kago bilong em, sapos em i no laik pasim dispela strongpela man pastaim. Na nau em bai kisim ol kago bilong haus bilong em.',
        28: 'Tru tumas, Mi tokim yupela, Olgeta sin bai God i lusim bilong ol pikinini man bilong ol man, na wanem kain ol tok bilas we ol bai tok bilas wantaim ol.',
        29: 'Tasol em husat bai tok bilas i birua long Holi Spirit i no gat rot long God bai lusim sin bilong em, tasol em i ken kisim bagarap bilong lus olgeta long kot oltaim oltaim.',
        30: 'Bilong wanem, ol i tok, Em i gat wanpela spirit i no klin.',
        31: '¶ Nau i gat i kam long Em ol brata bilong Em na mama bilong Em, na, taim ol i sanap ausait, ol i salim tok long Em, na singautim Em.',
        32: 'Na bikpela lain tru i sindaun nabaut long Em, na ol i tokim Em, Lukim, mama bilong Yu na ol brata bilong Yu i stap ausait na painim Yu.',
        33: 'Na Em i bekim tok long ol, i spik, Mama bilong Mi em husat, o ol brata bilong Mi?',
        34: 'Na Em i lukluk raun nabaut long ol husat i sindaun nabaut long Em, na tok, Lukim mama bilong Mi na ol brata bilong Mi!',
        35: 'Long wanem, husat man bai mekim laik bilong God, em yet em i brata bilong Mi, na susa bilong mi, na mama bilong Mi.',
    },
    4: {
        1: '¶ Na Em i stat gen long skulim ol manmeri klostu long biksi. Na i gat i bung long Em wanpela traipela lain tru, inap long Em i go insait long wanpela sip, na sindaun long biksi. Na dispela bikpela lain tru olgeta i stap klostu long biksi long nambis.',
        2: 'Na Em i skulim ol long planti samting long ol tok piksa, na tokim ol long skul bilong Em,',
        3: 'Harim. Lukim, i gat i go ausait wanpela man bilong planim bilong planim.',
        4: 'Na em i kamap olsem, taim em i planim, sampela i pundaun klostu long sait bilong rot, na ol pisin bilong skai i kam na kaikai dispela olgeta.',
        5: 'Na sampela i pundaun long graun i gat ston, we em i no gat planti graun. Na wantu em i kam antap, bilong wanem, em i no gat graun i dip.',
        6: 'Tasol taim san i kam antap, em i kuk. Na bikos em i no gat rop daunbilo, em i go drai olgeta.',
        7: 'Na sampela i pundaun namel long ol rop i gat nil, na ol rop i gat nil i go bikpela, na pasim nek bilong en, na em i no karim kaikai.',
        8: 'Na arapela i pundaun long gutpela graun, na i bin karim dispela kaikai i kam antap na kamap planti moa. Na em i karim, sampela 30, sampela 60, na sampela 100.',
        9: 'Na Em i tokim ol, Em husat i gat ol ia bilong harim, larim em harim.',
        10: 'Na taim Em i stap wanpela, ol husat i stap nabaut long Em wantaim dispela twelpela i askim Em long dispela tok piksa.',
        11: 'Na Em i tokim ol, Long yupela God i givim long yupela i ken save long ol samting hait bilong kingdom bilong God. Tasol long ol husat i stap ausait, olgeta dispela samting Mi mekim em long ol tok piksa.',
        12: 'Inap long taim ol i lukim ol i ken lukim, na ol i no ken kisim save. Na taim ol i harim ol i ken harim, na ol i no ken kisim save. Nogut long wanpela taim ol i ken senisim bilip, na God i ken lusim ol sin bilong ol.',
        13: 'Na Em i tokim ol, Ating i yes long yupela i save long dispela tok piksa? Na nau olsem wanem bai yupela i ken save long olgeta tok piksa?',
        14: 'Man bilong planim i planim tok bilong God.',
        15: 'Na ol dispela em ol husat i stap klostu long sait bilong rot, we em i planim tok bilong God. Tasol taim ol i bin harim, Seten i kam wantu, na kisim dispela tok i go, dispela em i planim insait long ol bel bilong ol.',
        16: 'Na ol dispela i wankain olsem ol husat em i planim long graun i gat ston. Husat, taim ol i harim tok bilong God, wantu ol i kisim dispela wantaim amamas.',
        17: 'Na ol i no gat rop daunbilo insait long ol yet, na olsem tasol ol i stap yet liklik taim tasol. Bihain long en, taim hevi o taim bilong kisim hevi i kirap bilong tingim tok bilong God, wantu bel bilong ol i bagarap.',
        18: 'Na ol dispela em ol husat em i planim namel long ol rop i gat nil. Kain olsem husat i harim tok bilong God,',
        19: 'Na ol wari bilong dispela graun, na ol giaman bilong ol mani samting, na ol aigris bilong ol arapela samting i kam insait, na pasim nek bilong tok bilong God, na em kamap samting i no karim kaikai.',
        20: 'Na ol dispela em ol husat em i planim long gutpela graun. Kain olsem husat i harim tok bilong God, na kisim, na karim kaikai, sampela 30 taims, sampela 60, sampela 100.',
        21: '¶ Na Em i tokim ol, Ating ol i bringim wanpela kandel bilong putim aninit long wanpela busel, o aninit long bet? Na ating i yes long ol i baim bilong putim antap long stik kandel?',
        22: 'Long wanem, i no gat wanpela samting hait, bai dispela i no inap kamap ples klia. Na tu i no gat wanpela samting ol i pasim hait, tasol long em i mas kam ausait.',
        23: 'Sapos wanpela man i gat ol ia bilong harim, larim em harim.',
        24: 'Na Em i tokim ol, Was gut long yupela i harim wanem. Wantaim wanem skel yupela i skelim, ol bai skelim dispela long yupela. Na long yupela husat i harim bai ol i givim moa.',
        25: 'Long wanem, em husat i gat, long em bai ol i givim. Na em husat i no gat, long em ol bai kisim, yes, dispela samting em i gat.',
        26: 'Na Em i tok, Kingdom bilong God i olsem, olsem sapos wanpela man i ken tromoi pikinini kaikai long graun.',
        27: 'Na em i ken slip, na kirap long nait na san, na long pikinini kaikai i ken sut i kam antap na go bikpela, em i no save olsem wanem.',
        28: 'Long wanem, dispela graun i karim kaikai long em yet. Kru pastaim, nau ia, bihain long dispela ia bilong wit samting i pulap.',
        29: 'Tasol taim kaikai i kam ausait, wantu em i putim sarip i go insait, bilong wanem, taim bilong kamautim kaikai i kam pinis.',
        30: 'Na Em i tok, Mi bai toktok long kingdom bilong God i olsem long wanem samting? O yumi bai skelim dispela wantaim wanem samting?',
        31: 'Em i wankain olsem wanpela hap pikinini kaikai bilong mastet, husat, taim ol i planim long dispela graun, em i liklik moa long olgeta dispela pikinini kaikai i stap long dispela graun.',
        32: 'Tasol taim ol i planim, em i go bikpela, na em i kamap bikpela moa long olgeta arapela sayor, na sutim ol bikpela han i go ausait, inap long ol pisin bilong skai i ken kam stap aninit long tewel bilong san bilong en.',
        33: 'Na wantaim planti kain tok piksa olsem Em i tokim ol long tok bilong God, olsem ol i inap long harim.',
        34: 'Tasol taim i no gat tok piksa Em i no tokim ol. Na taim ol i stap ol yet tasol, Em i kolim gut olgeta samting long ol disaipel bilong Em.',
        35: '¶ Na long dispela de stret, taim apinun tru i kam pinis, Em i tokim ol, Yumi go hapsait i go long arapela sait.',
        36: 'Na taim ol i bin salim bikpela lain tru i go, ol i kisim Em, yes, taim Em i stap insait long sip. Na i gat i stap tu wantaim Em ol arapela liklik sip.',
        37: 'Na i gat wanpela bikpela win nogut i kirap, na ol sibruk i paitim paitim sip, inap long nau em i pulap.',
        38: 'Na Em i stap long hap bilong sip i stap long baksait, na Em i slip long wanpela pilo. Na ol i kirapim Em, na tokim Em, Tisa, ating i yes long Yu no wari long mipela i wok long dai olgeta?',
        39: 'Na Em i kirap, na hatim win, na tokim biksi, Bel isi, stap isi. Na win i pinis, na si i stap isi tru olgeta.',
        40: 'Na Em i tokim ol, Bilong wanem yupela i pulap long pret olsem? Olsem wanem na em i stap long yupela i no gat bilip tru?',
        41: 'Na ol i pret planti moa yet, na tok wanpela i go long narapela, Dispela em i wanem kain Man, long yes, win na biksi i bihainim tok bilong Em?',
    },
    5: {
        1: '¶ Na ol i kam hapsait i go long arapela sait bilong biksi, i go long hap graun bilong ol lain Gadara.',
        2: 'Na taim Em i kam ausait long sip, wantu wanpela man i gat wanpela spirit i no klin i kam ausait long ol matmat i bungim Em,',
        3: 'Husat i gat ples bilong sindaun bilong em namel long ol matmat. Na i no gat man i ken pasim em, nogat, i no wantaim ol sen.',
        4: 'Bilong wanem, long planti taim ol i bin pasim em wantaim ol samting bilong pasim lek na ol sen, na em i bin brukim ol sen long ol hap, na ol samting bilong pasim lek i bruk long ol liklik hap. Na tu i no gat wanpela man i ken mekim em long sindaun isi.',
        5: 'No olgeta taim, nait na san, em i stap long ol maunten, na long ol matmat, na singaut, na katim em yet wantaim ol ston.',
        6: 'Tasol taim em i lukim Jisas longwe, em i ran na lotuim Em,',
        7: 'Na singaut wantaim bikpela nek, na tok, Mi gat wanem samting wantaim Yu, Jisas, Yu Pikinini Man bilong God i antap olgeta? Mi tok strong long Yu long God, long Yu no givim traipela pen long mi.',
        8: 'Long wanem, Em i tokim em, Kam ausait long dispela man, yu spirit i no klin.',
        9: 'Na Em i askim em, Wanem nem bilong yu? Na em i bekim tok, i spik, Nem bilong mi em Lijon. Long wanem, mipela i planti.',
        10: 'Na em i askim Em long daun pasin planti long Em i no inap salim ol i go ausait long dispela hap graun.',
        11: 'Nau i gat long dispela hap klostu long ol maunten, wanpela bikpela lain pik i kaikai.',
        12: 'Na olgeta spirit nogut i askim Em long daun pasin, i spik, Salim mipela i go insait long ol pik, inap long mipela i ken go insait long ol.',
        13: 'Na wantu Jisas i tok orait long ol. Na ol spirit i no klin i go ausait, na go insait long ol pik. Na dispela lain pik i ran wantaim pasin pait i go daun long ples i maunten tru i go long biksi, (ol i klostu olsem 2,000,) na biksi i pasim nek bilong ol.',
        14: 'Na ol husat i givim kaikai long ol pik i ranawe, na toksave long dispela insait long biktaun, na long dispela hap graun. Na ol i go ausait long lukim dispela samting Em i mekim em wanem.',
        15: 'Na ol i kam long Jisas, na lukim em husat dispela spirit nogut i bin holimpas, na i bin gat dispela lijon, i sindaun, na werim klos, na tingting bilong em i stap stret. Na ol i pret.',
        16: 'Na ol husat i lukim dispela i tokim ol long em i kamap olsem wanem long em husat spirit nogut i bin holimpas, na tu long sait bilong ol pik.',
        17: 'Na ol i stat long askim Em plis long i go ausait long ol hap arere bilong ol.',
        18: 'Na taim Em i kam insait long sip, em husat dispela spirit nogut i bin holimpas i askim Em plis long em i ken stap wantaim Em.',
        19: 'Tasol Jisas i no larim em, tasol Em i tokim em, Go long haus bilong yu long ol pren bilong yu, na tokim ol long ol bikpela samting moa Bikpela i bin mekim bilong helpim yu, na long Em i bin gat pasin sori long yu.',
        20: 'Na em i lusim Em, na stat long mekim i kamap ples klia long Dekapolis ol bikpela samting moa Jisas i bin mekim bilong helpim em. Na olgeta man i bin tingting planti.',
        21: '¶ Na taim Jisas i go hapsait gen long sip long arapela sait, planti manmeri i bung long Em. Na Em i stap klostu long biksi.',
        22: 'Na, lukim, i gat i kam wanpela bilong ol hetman bilong sinagog, Jairas em i nem bilong em. Na taim em i lukim Em, em i pundaun long tupela lek bilong Em,',
        23: 'Na askim Em long bikpela daun pasin, i spik, Liklik pikinini meri bilong mi i stap klostu tru long dai. Mi askim Yu plis, kam na slipim tupela han bilong Yu antap long em, inap long em i ken kamap orait gen. Na em bai stap laip.',
        24: 'Na Jisas i go wantaim em. Na planti manmeri i bihainim Em, na pas klostu strong long Em.',
        25: 'Na wanpela meri, husat i gat blut i kam ausait twelpela yia,',
        26: 'Na i bin karim pen long planti samting long han bilong planti dokta, na i bin yusim olgeta samting em i gat, na i no kamap gutpela moa liklik, tasol em i go nogut moa,',
        27: 'Taim em i bin harim stori long Jisas, em i kam long baksait insait long ol man i pas pas tumas, na tasim klos bilong Em.',
        28: 'Long wanem, em i tok, Sapos mi ken tasim klos bilong Em tasol, Mi bai kamap orait olgeta.',
        29: 'Na kwiktaim ai bilong wara i sut bilong blut bilong em i go drai. Na em i pilim insait long bodi bilong em long em i kamap orait gen long dispela sik nogut.',
        30: 'Na Jisas, wantu Em i save insait long Em Yet long gutpela strong i bin go ausait long Em, na Em i tanim nabaut insait long ol man i pas pas tumas, na tok, Husat i tasim klos bilong Mi?',
        31: 'Na ol disaipel bilong Em i tokim Em, Yu luksave long bikpela lain tru i pas klostu strong long Yu, na Yu tok, Husat i tasim Mi?',
        32: 'Na Em i lukluk raun nabaut long lukim meri husat i bin mekim dispela samting.',
        33: 'Tasol taim meri i pret na guria, taim em i save wanem samting i bin kamap insait long em yet, i kam na pundaun long ai bilong Em, na tokim Em long olgeta tok tru.',
        34: 'Na Em i tokim em, Pikinini meri, bilip tru bilong yu i bin mekim yu orait olgeta. Go wantaim bel isi, na stap orait olgeta long sik nogut bilong yu.',
        35: '¶ Taim Em i toktok yet, i gat i kam long haus bilong hetman bilong sinagog sampela husat i tok, Pikinini meri bilong yu i dai pinis. Bilong wanem yu givim sampela wari moa long Tisa?',
        36: 'Long taim stret long Jisas i harim dispela tok ol i toktok, Em i tokim hetman bilong sinagog, No ken pret, bilip tasol.',
        37: 'Na Em i no larim wanpela arapela man i ken bihainim Em, Pita tasol, na Jems, na Jon, brata bilong Jems.',
        38: 'Na Em i kam long haus bilong hetman bilong sinagog, na lukim dispela bikpela paul nabaut, na ol husat i krai tru na krai wantaim bikpela singaut.',
        39: 'Na taim Em i kam insait, Em i tokim ol, Bilong wanem yupela i wokim dispela samting, na krai tru? Dispela yangpela meri i no dai pinis, em i slip tasol.',
        40: 'Na ol i lap long Em inap long sem bilong tok bilas. Tasol taim Em i bin putim olgeta i go ausait, Em i kisim papa na mama bilong dispela yangpela meri, na ol husat i stap wantaim Em, na ol i go insait long hap we yangpela meri i slip long bet.',
        41: 'Na Em i kisim han bilong yangpela meri, na tokim em, Talita kumi. Dispela i olsem, taim yumi tanim tok, Yangpela meri, Mi tokim yu, kirap.',
        42: 'Na kwiktaim dispela yangpela meri i kirap, na wokabaut. Long wanem, em i gat twelpela krismas. Na ol i kirap nogut wantaim wanpela bikpela kirap nogut.',
        43: 'Na Em i givim tok long ol stret long i no gat man i ken save long dispela. Na Em i tok strong long ol i ken givim meri samting long kaikai.',
    },
    6: {
        1: '¶ Na Em i go ausait long dispela ples, na kam insait long hap bilong Em Yet. Na ol disaipel bilong Em i bihainim Em.',
        2: 'Na taim de sabat i kam pinis, Em i stat long skulim ol manmeri insait long sinagog. Na planti, taim ol i harim Em, i kirap nogut, i spik, Dispela Man i bin kisim ol dispela samting long we? Na dispela save tru God i givim Em em wanem, inap long yes, ol kain strongpela wok olsem Em i wokim long tupela han bilong Em?',
        3: 'Ating i yes long dispela em i kamda, pikinini man bilong Maria, brata bilong Jems, na Joses, na bilong Juda, na Saimon? Na ating i yes long ol susa bilong Em i stap hia wantaim yumi? Na bel bilong ol i bagarap long Em.',
        4: 'Tasol Jisas i tokim ol, Profet i no sot olgeta long ona, long hap bilong em yet tasol, na namel long ol kandre bilong em, na insait long hauslain bilong em yet.',
        5: 'Na Em i no inap wokim strongpela wok long dispela hap, Em i putim tupela han bilong Em antap long wan wan bilong ol manimeri i sik tasol, na oraitim ol.',
        6: 'Na Em i tingting planti, bilong wanem, ol i no gat bilip. Na Em i go raun nabaut long ol vilis, na skulim ol manmeri.',
        7: '¶ Na Em i singautim i kam long Em dispela twelpela, na Em i stat long salim ol i go ausait long tupela tupela. Na Em i givim pawa long ol long bosim ol spirit i no klin.',
        8: 'Na Em i tok strong long ol long ol i no ken karim wanpela arapela samting long wokabaut bilong ol, stik wokabaut tasol. Ol i no ken karim liklik bek, o bret, o mani long paus mani bilong ol.',
        9: 'Tasol su bilong ol i mas ol slipa. Na ol i no ken putim tupela saket.',
        10: 'Na Em i tokim ol, Long wanem ples olgeta yupela i go insait long wanpela haus, stap long dispela hap inap long yupela lusim dispela ples.',
        11: 'Na husat man i no laik kisim yupela, o harim yupela, taim yupela i lusim dispela ples, seksekim das i lusim aninit bilong ol lek bilong yupela bilong wanpela testimoni i birua long ol. Tru tumas, Mi tokim yupela, Em bai stap orait moa long Sodom na Gomora long de bilong kot, moa long dispela biktaun.',
        12: 'Na ol i go ausait, na autim tok long ol man i mas tanim bel.',
        13: 'Na ol i rausim planti spirit nogut, na makim wantaim wel planti husat i sik, na oraitim ol.',
        14: '¶ Na king Herot i harim stori long Em. (Long wanem, nem bilong Em i go nabaut ausait.) Na em i tok, Long Jon dispela Baptist i kirap bek long dai, na olsem na ol strongpela wok i soim ol yet insait long Em.',
        15: 'Ol arapela i tok, Long dispela em Ilaias. Na ol arapela i tok, Long dispela em wanpela profet, o olsem wanpela bilong ol profet.',
        16: 'Tasol taim Herot i harim long en, em i tok, Dispela em Jon, husat mi bin rausim het bilong em. Em i kirap bek long dai.',
        17: 'Long wanem, Herot em yet i bin salim tok i go ausait na holimpas Jon, na pasim em insait long kalabus bilong tingim Herodias, meri bilong brata bilong em Filip. Long wanem, em i bin maritim em.',
        18: 'Long wanem, Jon i bin tokim Herot, Em i no orait long lo long yu ken kisim meri bilong brata bilong yu.',
        19: 'Olsem na Herodias i gat wanpela kros i birua long em, na em i gat laik long kilim em. Tasol em i no inap.',
        20: 'Long wanem, Herot i pret long Jon, taim em save long em i wanpela stretpela man na holi, na em i lukluk long em. Na taim em i harim em, em i mekim planti samting, na harim em wantaim amamas.',
        21: 'Na taim wanpela fit de i kam, long Herot, long de bilong tingim de mama i karim em, i wokim wanpela apinun kaikai i go long ol bikman bilong em, ol kepten i antap, na ol nambawan bikman bilong Galili.',
        22: 'Na taim pikinini meri bilong dispela Herodias i kam insait, na danis, na amamasim bel bilong Herot na ol husat i sindaun wantaim em, king i tokim dispela yangpela meri, Askim long mi wanem samting yu laikim, na mi bai givim dispela long yu.',
        23: 'Na em i wokim strongpela promis i go long em, Wanem samting yu bai askim long mi, mi bai givim dispela long yu, inap long namba tu hap bilong kingdom bilong mi.',
        24: 'Na meri i go ausait, na tokim mama bilong em, Mi bai askim wanem samting? Na em i tok, Het bilong Jon dispela Baptist.',
        25: 'Na em i kam insait kwiktaim, wantaim pasin bilong hariap, i go long king, na askim, i spik, Mi gat laik long yu givim mi bambai, long wanpela bikpela dis, het bilong Jon dispela Baptist.',
        26: 'Na king i sori planti moa yet. Tasol bilong tingim strongpela promis bilong em, na bilong tingim ol husat i sindaun wantaim em, em i no inap tok nogat olgeta long em.',
        27: 'Na wantu king i salim wanpela man bilong mekim man i dai, na tok strong long bringim het bilong em. Na em i go na rausim het bilong em long kalabus,',
        28: 'Na bringim het bilong em long wanpela bikpela dis, na givim dispela long yangpela meri. Na yangpela meri i givim dispela long mama bilong em.',
        29: 'Na taim ol disaipel bilong em i harim stori long dispela, ol i kam na kisim daibodi bilong em, na slipim insait long matmat.',
        30: '¶ Na ol aposel i bungim ol yet wantaim i go long Jisas, na toksave long Em long olgeta samting, wanem samting ol i bin mekim, na wanem samting ol i bin skulim ol manmeri wantaim.',
        31: 'Na Em i tokim ol, Yupela kam stap yupela yet i go long ples i no gat man, na malolo liklik. Long wanem, i gat planti husat i kam na go, na ol i no gat taim malolo liklik inap long ol i ken kaikai.',
        32: 'Na ol i lusim dispela hap i go long ples i no gat man long wanpela sip ol yet.',
        33: 'Na ol manmeri i lukim ol i lusim dispela hap, na planti i save long Em, na ran long lek i go long dispela hap ausait long olgeta biktaun, na kam pastaim long ol, na kam bung wantaim i go long Em.',
        34: 'Na Jisas, taim Em i kam ausait, i lukim planti manmeri, na pasin sori i muvim bel bilong Em i go long ol, bilong wanem, ol i olsem ol sipsip i no gat wasman. Na Em i stat long skulim ol long planti samting.',
        35: 'Na taim de i klostu long pinis nau, ol disaipel bilong Em i kam long Em, na tok, Dispela em i ples i no gat man, na nau taim em i go pinis tru.',
        36: 'Salim ol i go, inap long ol i ken go long hap raun nabaut, na long ol vilis, na baim bret bilong ol yet. Long wanem, ol i no gat wanpela samting bilong kaikai.',
        37: 'Na Em i bekim na tokim ol, Yupela givim ol bilong kaikai. Na ol i tokim Em, Mipela bai go na baim bret long 200 peni, na givim ol bilong kaikai?',
        38: 'Na Em i tokim ol, Yupela i gat hamas hap bret? Go na luksave. Na taim ol i save, ol i tok, Faipela, na tupela pis.',
        39: 'Na Em i tok strong long ol long mekim olgeta manmeri sindaun long ol lain bung antap long grinpela gras.',
        40: 'Na ol i sindaun long ol gutpela lain, long ol 100, na long ol 50.',
        41: 'Na taim Em i bin kisim dispela faipela hap bret na tupela pis, Em i lukluk i go antap long heven, na blesim, na brukim ol hap bret, na givim ol long ol disaipel bilong Em bilong putim long ai bilong ol. Na dispela tupela pis Em i brukim namel long ol olgeta.',
        42: 'Na ol olgeta i bin kaikai, na ol i pulap.',
        43: 'Na ol i bungim twelpela basket i pulap long ol hap hap kaikai, na bilong ol pis.',
        44: 'Na ol husat i bin kaikai long ol dispela hap bret em i klostu olsem 5,000 man.',
        45: '¶ Na kwiktaim Em i pulim ol disaipel bilong Em strong long go insait long sip, na long go long arapela sait paslain i go long Betsaida, taim Em i salim ol manmeri i go.',
        46: 'Na taim Em i bin salim ol i go, Em i lusim dispela hap i go long wanpela maunten bilong beten.',
        47: 'Na taim apinun tru i kam pinis, sip i stap insait long namel bilong biksi, na Em i stap Em wanpela long nambis.',
        48: 'Na Em i lukim ol i hatwok long pul. Long wanem, win i birua long ol. Na klostu long namba foa was bilong nait Em i kam long ol, taim Em i wokabaut antap long biksi, na Em i gat laik long wokabaut i abrusim ol.',
        49: 'Tasol taim ol i lukim Em i wokabaut antap long biksi, ol i ting olsem dispela i bin stap wanpela spirit, na ol i singaut.',
        50: 'Long wanem, ol olgeta i lukim Em, na ol i pilim wari. Na wantu Em i toktok wantaim ol, na tokim ol, Stap wantaim gutpela amamas. Em Mi. No ken pret.',
        51: 'Na Em i go antap i go long ol insait long sip. Na win i pinis. Na ol i kirap nogut tru strong tru insait long ol yet i go abrusim skel, na ol i tingting planti.',
        52: 'Long wanem, ol i no tingim na skelim dispela mirakel bilong ol hap bret. Long wanem, bel bilong ol i kamap olsem ston.',
        53: 'Na taim ol i bin go hapsait, ol i kam long hap graun bilong Genesaret, na wok long go klostu long nambis.',
        54: 'Na taim ol i kam ausait long sip, kwiktaim ol manmeri i save long Em,',
        55: 'Na ran namel long dispela hap graun olgeta raun nabaut, na stat long karim nabaut long ol bet ol dispela husat i sik, we ol i harim long Em i stap.',
        56: 'Na long wanem hap we Em i go, long ol vilis, o ol biktaun, o hap i no gat planti man, ol i slipim ol sikman long ol rot, na askim Em long daun pasin inap long ol i ken tasim, sapos em i olsem, arere bilong klos bilong Em tasol. Na hamas manmeri i tasim Em i kamap orait olgeta.',
    },
    7: {
        1: '¶ Nau ol Farisi, na sampela bilong ol man bilong rait, husat i kam long Jerusalem, i kam bung wantaim i go long Em.',
        2: 'Na taim ol i lukim sampela bilong ol disaipel bilong Em i kaikai bret wantaim ol han i doti, dispela tok em i olsem, wantaim ol han ol i no wasim, ol i putim asua.',
        3: 'Long wanem, ol Farisi, na olgeta Ju, sapos ol i no wasim ol han bilong ol planti taim, ol i no kaikai, taim ol i holimpas kastam bilong ol lapun hetman.',
        4: 'Na taim ol i kam bek long maket, sapos ol i no wasim, ol i no kaikai. Na planti arapela ol samting i stap, dispela ol i bin kisim bilong holimpas, olsem pasin bilong wasim ol kap, na ol sospen, na ol sospen samting bras, na ol tebol.',
        5: 'Nau ol Farisi na ol man bilong rait i askim Em, Bilong wanem ol disaipel bilong Yu i no wokabaut bilong bihainim kastam bilong ol lapun hetman, tasol ol i kaikai bret wantaim ol han ol i no wasim?',
        6: 'Em i bekim na tokim ol, Aisea i bin autim tok profet gut long yupela ol man bilong tupela maus, olsem rait i stap pinis, Dispela lain manmeri i givim ona long Mi wantaim ol lip bilong ol, tasol bel bilong ol i stap longwe long Mi.',
        7: 'Tasol ol i lotuim Mi nating, taim ol i skulim ol man long ol tok strong bilong ol man na tok em ol skul bilong God.',
        8: 'Long wanem, taim yupela i slipim long sait ol tok strong bilong God, yupela i holimpas kastam bilong ol man, olsem bilong wasim ol sospen na ol kap. Na planti arapela kain samting olsem yupela i mekim.',
        9: 'Na Em i tokim ol, Yupela i givim baksait gutpela tru olgeta long tok strong bilong God, inap long yupela i ken holimpas kastam bilong yupela yet.',
        10: 'Long wanem, Moses i tok, Givim ona long papa bilong yu na mama bilong yu. Na, Husat man i toknogutim papa o mama, larim em dai long dispela dai.',
        11: 'Tasol yupela i tok, Sapos wanpela man bai tokim papa bilong em o mama, Em i Korban, dispela tok em i olsem, wanpela presen, long wanem samting yu ken winim pinis long mi, em bai stap fri.',
        12: 'Na yupela i no larim em mekim samting moa long helpim papa bilong em ol mama bilong em.',
        13: 'Na long wok bilong kastam bilong yupela, dispela yupela i bin givim, yupela i mekim tok bilong God bilong i no gat pawa. Na planti kain samting olsem yupela i mekim.',
        14: 'Na taim Em i bin singautim olgeta manmeri i kam long Em, Em i tokim ol, Harim long Mi olgeta wan wan bilong yupela, na kisim save.',
        15: 'I no gat wanpela samting i kam long ausait bilong man, long taim dispela i go insait long em i ken mekim em doti. Tasol ol dispela samting i kam ausait long em, ol dispela em ol samting i mekim man doti.',
        16: 'Sapos wanpela man i gat tupela ia bilong harim, larim em harim.',
        17: 'Na taim Em i lusim ol manmeri i go insait long dispela haus, ol disaipel bilong Em i askim Em long sait bilong dispela tok piksa.',
        18: 'Na Em i tokim ol, Ating i yes yupela i no gat save tu olsem? Ating i yes long yupela i no kisim save, long wanem kain samting i kam long ausait i go insait long man, dispela i no inap long mekim em doti,',
        19: 'Bilong wanem, em i no go insait long bel tru bilong em, tasol insait long bel bilong bodi bilong em, na em i go ausait insait long ol pipia, taim man i rausim olgeta pipia bilong kaikai?',
        20: 'Na Em i tok, Dispela samting i kam ausait long man, dispela i mekim man doti.',
        21: 'Long wanem, long insait, ausait long bel bilong ol man, ol tingting nogut i kam, ol pasin bilong bagarapim marit long pamuk pasin, ol pamuk pasin, ol pasin bilong kilim man,',
        22: 'Ol stil pasin, pasin mangal, pasin nogut, pasin giaman, pasin bilong mangal nogut, ai bilong pasin nogut, tok bilas, hambak pasin, kranki pasin.',
        23: 'Olgeta dispela samting nogut i kam long insait, na mekim man i doti.',
        24: '¶ Na long dispela ples Em i kirap, na go long ol hap arere bilong Tair na Saidon, na go insait long wanpela haus, na Em i no gat laik long wanpela man i ken save long dispela. Tasol Em i no inap long stap hait.',
        25: 'Long wanem, wanpela meri, husat yangpela pikinini meri bilong em i gat wanpela spirit i no klin, i harim stori long Em, na em i kam na pundaun long tupela lek bilong Em.',
        26: 'Dispela meri em i wanpela Grik, kantri bilong em em hap Finisia bilong Siria. Na em i askim Em long daun pasin long Em i ken rausim dispela spirit nogut i kam ausait long pikinini meri bilong em.',
        27: 'Tasol Jisas i tokim em, Larim ol pikinini i ken pulap pastaim. Long wanem, em i no fit long kisim bret bilong ol pikinini, na tromoi dispela i go long ol dok.',
        28: 'Na em i bekim na tokim Em, Yes, Bikpela. Tasol ol dok i stap aninit long tebol i kaikai ol pipia bilong kaikai bilong ol pikinini.',
        29: 'Na Em i tokim em, Long dispela toktok bilong yu, go long rot bilong yu. Dispela spirit nogut i lusim pikinini meri bilong yu pinis.',
        30: 'Na taim em i kam long haus bilong em, em i luksave long spirit nogut i bin go ausait pinis, na pikinini meri bilong em i slip long bet.',
        31: '¶ Na gen, taim Em i lusim ol hap arere bilong Tair na Saidon, Em i kam long biksi Galili, taim Em i bin brukim namel bilong ol hap arere bilong Dekapolis.',
        32: 'Na ol i bringim long Em wanpela husat i iapas, na i gat wanpela samting i pasim em long toktok gut. Na ol i askim Em long daun pasin long putim han bilong Em antap long em.',
        33: 'Na Em i kisim em i go long sait i lusim dispela bikpela lain tru, na putim ol pinga bilong Em insait long tupela ia bilong em, na Em i spet, na tasim tang bilong em.',
        34: 'Na taim Em i lukluk i go antap long heven, Em i lusim win bilong soim wari, na tokim em, Efata, em i olsem, Stap op.',
        35: 'Na kwiktaim tupela ia bilong em i op, na string bilong tang bilong em i lus, na em i toktok klia.',
        36: 'Na Em i givim strongpela tok long ol long ol i no ken tokim wanpela man. Tasol hamas moa Em i givim tok long ol, olsem tasol hamas i planti moa tru long ol i mekim dispela i kamap ples klia.',
        37: 'Na ol i kirap nogut i go abrusim skel, i spik, Em i bin mekim olgeta samting gutpela. Em i mekim ol iapas long harim, na ol mauspas long toktok wantaim.',
    },
    8: {
        1: '¶ Long ol dispela de taim dispela bikpela lain tru i stap bikpela tru, na taim ol i no gat wanpela samting bilong kaikai, Jisas i singautim ol disaipel bilong Em long kam long Em, na tokim ol,',
        2: 'Mi gat pasin sori long dispela bikpela lain tru, bilong wanem, ol i bin stap wantaim Mi nau tripela de, na ol i no gat wanpela samting bilong kaikai.',
        3: 'Na sapos Mi salim ol i go long ol haus bilong ol yet taim ol i tambuim kaikai, ol bai hap i dai long rot. Long wanem, kain kain bilong ol i kam long longwe ples.',
        4: 'Na ol disaipel bilong Em i bekim tok long Em, Bret bilong inapim ol dispela man bai kam long we hia long dispela ples i no gat man?',
        5: 'Na Em i askim ol, Yupela i gat hamas hap bret? Na ol i tok, sevenpela.',
        6: 'Na Em i tok strong long ol manmeri long sindaun long graun. Na Em i kisim dispela sevenpela hap bret, na givim tok tenkyu, na brukim, na givim long ol disaipel bilong Em bilong putim long ai bilong ol. Na ol i bin putim ol long ai bilong ol manmeri.',
        7: 'Na ol i gat wan wan liklik pis. Na Em i blesim, na tok strong long putim ol tu long ai bilong ol.',
        8: 'Olsem na ol i bin kaikai, na ol i pulap. Na ol i bungim bilong ol hap kaikai i bruk bruk, dispela i stap yet, sevenpela basket.',
        9: 'Na ol husat i bin kaikai i klostu olsem 4,000. Na Em i salim ol i go.',
        10: '¶ Na kwiktaim Em i go insait long wanpela sip wantaim ol disaipel bilong Em, na kam insait long ol hap bilong Dalmanuta.',
        11: 'Na ol Farisi i kam ausait, na ol i stat long wokim askim wantaim Em, taim ol i painim long Em wanpela mak i kam long heven, taim ol i traim Em.',
        12: 'Na Em i lusim win bilong soim wari bikpela insait long spirit bilong Em, na tok, Bilong wanem dispela lain tumbuna i painim i bihainim wanpela mak? Tru tumas, Mi tokim yupela, God bai i no inap givim wanpela mak long dispela lain tumbuna.',
        13: 'Na Em i lusim ol, na taim Em i go insait long sip gen ol i lusim dispela hap i go long arapela sait.',
        14: 'Nau ol disaipel i bin lusim tingting long kisim bret, na tu ol i no gat wantaim ol long sip moa long wanpela hap bret.',
        15: 'Na Em i givim tok long ol, i spik, Was gut, lukaut gut long yis bilong ol Farisi, na long yis bilong Herot.',
        16: 'Na ol i wok long stretim tok namel long ol yet, i spik, Em i bikos yumi no gat bret.',
        17: 'Na taim Jisas i save long dispela, Em i tokim ol, Bilong wanem yupela i wok long stretim tok olsem, bikos yupela i no gat bret? Ating i yes long yupela i no kisim save yet, na tu yupela i no gat save? Ating yupela i bin mekim bel bilong yupela i olsem ston yet?',
        18: 'Taim yupela i gat ol ai, yupela i no lukluk? Na taim yupela i gat ol ia, yupela i no harim? Na ating i yes long yupela i no holim tingting?',
        19: 'Taim Mi brukim faipela hap bret namel long yupela, hamas basket i pulap long ol hap hap kaikai yupela i bin kisim i go antap? Ol i tokim Em, twelpela.',
        20: 'Na taim dispela sevenpela namel long 4,000, hamas basket i pulap long ol hap hap bilong kaikai yupela i kisim i go antap? Na ol i tok, sevenpela.',
        21: 'Na Em i tokim ol, Olsem wanem em i olsem long yupela i no gat save?',
        22: '¶ Na Em i kam long Betsaida. Na ol i bringim wanpela aipas man long Em, na askim Em long daun pasin long tasim em.',
        23: 'Na Em i kisim dispela aipas man long han, na bringim em ausait long taun. Na taim Em i bin spet long tupela ai bilong em, na putim tupela han bilong Em antap long em, Em i askim em long sapos em i lukim wanpela samting.',
        24: 'Na em i lukluk i go antap, na tok, Mi lukim ol man olsem diwai, na ol i wokabaut.',
        25: 'Bihain long dispela Em i putim tupela han bilong Em gen long tupela ai bilong em, na mekim em lukluk i go antap. Na em i kamap orait gen, na lukim olgeta wan wan man klia.',
        26: 'Na Em i salim Em i go long haus bilong em, i spik, No ken go insait long taun, o tokim dispela long wanpela insait long taun.',
        27: '¶ Na Jisas i go ausait, na ol disaipel bilong Em, i go insait long ol taun bilong Sisaria Filipai. Na long rot Em i askim ol disaipel bilong Em, i spik long ol, Ol man i tok long Mi husat?',
        28: 'Na ol i bekim tok, Jon dispela Baptist. Tasol sampela i tok, Ilaias. Na ol arapela, Wanpela bilong ol profet.',
        29: 'Na Em i tokim ol, Tasol yupela i tok long Mi husat? Na Pita i bekim na tokim Em, Yu stap dispela Kraist.',
        30: 'Na Em i givim tok long ol long ol i no ken tokim wanpela man long Em.',
        31: 'Na Em i stat long skulim ol, long Pikinini Man bilong man i mas karim pen long planti samting, na ol lapun hetman mas tok nogat olgeta long Em, na ol bikpris, na ol man bilong rait, na ol i mas kilim Em, na bihain long tripela de Em i mas kirap bek gen.',
        32: 'Na Em i tok long dispela toktok ples klia. Na Pita i kisim Em, na em i stat long hatim Em.',
        33: 'Tasol taim Em i bin tanim nabaut na lukluk long ol disaipel bilong Em, Em i hatim Pita, i spik, Yu go baksait long Mi, Seten. Long wanem, yu no laikim ol dispela samting i stap bilong God, tasol ol dispela samting i stap bilong ol man.',
        34: 'Na taim Em i bin singautim ol manmeri i kam long Em wantaim ol disaipel bilong Em tu, Em i tokim ol, Husat man i gat laik long kam bihainim Mi, larim em tok nogat long em yet, na kisim diwai kros bilong em, na bihainim Mi.',
        35: 'Long wanem, husat man i gat laik long kisim bek laip bilong em bai lusim dispela. Tasol husat man bai lusim laip bilong em bilong tingim Mi na nem bilong gutnius, em yet bai kisim bek dispela.',
        36: 'Long wanem, em bai helpim man olsem wanem, sapos em bai winim dispela graun olgeta, na lusim tewel bilong em yet?',
        37: 'O man bai givim wanem bilong senisim tewel bilong em?',
        38: 'Olsem na husat man bai sem long Mi na bilong ol toktok bilong Mi long dispela lain tumbuna i lain bilong bagarapim marit long pamuk pasin na i pulap long sin, long em tu bai Pikinini Man bilong man bai sem, taim Em i kam long glori bilong Papa bilong Em wantaim ol ensel holi.',
    },
    9: {
        1: '¶ Na Em i tokim ol, Tru tumas, Mi tokim yupela, Long i gat sampela bilong yupela husat i sanap long hia, husat bai i no inap testim dai, inap long ol i bin lukim kingdom bilong God i kam wantaim pawa.',
        2: 'Na bihain long sikispela de Jisas i kisim wantaim Em Pita, na Jems, na Jon, na bringim ol i go antap long wanpela maunten antap long stap ol yet. Na bodi bilong Em i senis i kamap narakain long ai bilong ol.',
        3: 'Na klos bilong Em i stat long lait, wait planti moa yet olsem ais. Olsem tasol olsem i no gat man bilong klinim klos long dispela graun i ken mekim ol wait.',
        4: 'Na i gat i kamap ples klia long ol Ilaias wantaim Moses. Na tupela i toktok wantaim Jisas.',
        5: 'Na Pita i bekim na tokim Jisas, Tisa, em i gutpela long mipela long i stap long hia. Na larim mipela mekim tripela haus holi, wanpela bilong Yu, na wanpela bilong Moses, na wanpela bilong Ilaias.',
        6: 'Long wanem, em i no save long em i mas tok wanem. Long wanem, ol i pret tru.',
        7: 'Na i gat wanpela klaut i karamapim ol. Na wanpela nek i kam ausait long klaut, i spik, Dispela em i Pikinini Man bilong Mi i stap klostu tru long bel bilong Mi. Harim Em.',
        8: 'Na wantu, taim ol i bin lukluk raun nabaut, ol i no lukim wanpela man moa, Jisas tasol wantaim ol yet.',
        9: 'Na taim ol i kam daun long maunten, Em i givim tok long ol long ol i no ken tokim wanpela man long wanem ol samting ol i bin lukim, inap long Pikinini Man bilong man i kirap bek pinis long dai.',
        10: 'Na ol i holimpas dispela toktok wantaim long ol yet, taim ol i gat askim wanpela i go long narapela long dispela kirap bek long dai i ken gat wanem mining.',
        11: 'Na ol i askim Em, i spik, Bilong wanem ol man bilong rait i tok long Ilaias i mas kam pastaim?',
        12: 'Na Em i bekim na tokim ol, Tru tumas, Ilaias i mas kam pastaim, na stretim bek olgeta samting. Na long rait i stap pinis long Pikinini Man bilong man olsem wanem, long Em i mas karim pen long planti samting, na ol bai mekim Em olsem samting nating.',
        13: 'Tasol Mi tokim yupela, Long em i tru Ilaias i kam pinis, na ol i bin mekim long em wanem kain samting ol i gat laik, olsem rait i stap pinis long sait bilong em.',
        14: '¶ Na taim Em i kam long ol disaipel bilong Em, Em i lukim wanpela traipela lain tru nabaut long ol, na ol man bilong rait i wokim ol askim wantaim ol.',
        15: 'Na kwiktaim olgeta manmeri, taim ol i lukim Em, i kirap nogut tru bikpela, na taim ol i ran long Em ol i tok gude long Em.',
        16: 'Na Em i askim ol man bilong rait, Yupela gat wanem askim wantaim ol?',
        17: 'Na wanpela bilong dispela bikpela lain tru i bekim na tok, Tisa, mi bin bringim long Yu pikinini man bilong mi, husat i gat wanpela mauspas spirit.',
        18: 'Na long wanem hap olgeta em i karim em, em i brukim skin bilong em. Na maus bilong em i kapsaitim waitpela spet, na kaikaim tit wantaim ol tit bilong em, na wok long go bun nating. Na mi tokim ol disaipel bilong Yu long ol i mas rausim em i go. Na ol i no inap.',
        19: 'Em i bekim em, na tok, O lain tumbuna i no gat bilip tru, Mi bai stap wantaim yupela inap long wanem taim? Mi bai karim pen long yupela inap long wanem taim? Bringim em i kam long Mi.',
        20: 'Na ol i bringim em i kam long Em. Na taim Em i lukim em, kwiktaim dispela spirit i brukim skin bilong em. Na em i pundaun long graun, na tantanim bodi na maus i kapsaitim waitpela spet.',
        21: 'Na Em i askim papa bilong em, Dispela i stat long kam long em long wanem taim? Na em i tok, Taim em i pikinini.',
        22: 'Na planti taim dispela i bin tromoi em i go insait long paia, na i go insait long ol wara, bilong bagarapim em olgeta. Tasol sapos Yu ken wokim wanpela samting, soim pasin sori long mipela, na helpim mipela.',
        23: 'Na Jisas i tokim em, Sapos yu ken bilip, i gat rot long olgeta samting i ken kamap long em husat i bilip.',
        24: 'Na kwiktaim papa bilong pikinini i singaut, na tok wantaim aiwara, Bikpela, mi bilip. Yu mas helpim pasin bilong i no gat bilip bilong mi.',
        25: 'Taim Jisas i luksave long ol manmeri i ran i kam bung wantaim, Em i hatim dispela paul spirit, i spik long em, Yu mauspas na iapas spirit, Mi givim tok long yu, kam ausait long em, na no ken go moa insait long em.',
        26: 'Na dispela spirit i singaut, na brukim em tru, na kam ausait long em. Na em i stap olsem wanpela i dai pinis, inap olsem long planti i tok, Em i dai pinis.',
        27: 'Tasol Jisas i kisim em long han, na litimapim em. Na em i kirap.',
        28: 'Na taim Em i kam insait long haus, ol disaipel bilong Em i askim Em ol yet, Bilong wanem mipela i no inap long rausim em i go ausait?',
        29: 'Na Em i tokim ol, Dispela kain i no ken kam ausait long wanpela arapela samting, tasol long prea na pasin bilong tambuim kaikai.',
        30: '¶ Na ol lusim dispela ples, na wokabaut namel long Galili. Na Em i no gat laik long wanpela man i ken save long dispela.',
        31: 'Long wanem, Em i skulim ol disaipel bilong Em, na tokim ol, Ol bai givim Pikinini Man bilong man i go long ol han bilong ol man, na ol bai kilim Em, na bihain long ol i kilim Em, Em bai kirap bek gen long namba tri de.',
        32: 'Tasol ol i no kisim save long dispela toktok, na ol i pret long askim Em.',
        33: 'Na Em i kam long Kaperneam. Na taim ol i stap long haus Em i askim ol, Dispela em i wanem samting long yupela i bin tok pait long en namel long yupela yet long rot?',
        34: 'Tasol ol i pasim ol maus bilong ol. Long wanem, long rot ol i bin tok pait namel long ol yet, husat bai stap nambawan.',
        35: 'Na Em i sindaun, na singautim dispela twelpela, na tokim ol, Sapos wanpela man i gat laik long kamap namba wan, em yet bai stap las bilong olgeta, na wokboi bilong olgeta.',
        36: 'Na Em i kisim wanpela pikinini, na putim em namel long ol. Na taim em i bin kisim em long tupela han bilong Em, Em i tokim ol,',
        37: 'Husat man bai kisim wanpela bilong ol kain pikinini long nem bilong Mi, i kisim Mi. Na husat man bai kisim Mi, i no kisim Mi, tasol Em husat i salim Mi.',
        38: 'Na Jon i bekim Em, i spik, Tisa, mipela lukim wanpela i rausim ol spirit nogut i go long nem bilong Yu, na em i no bihainim yumi. Na mipela i tambuim em, bilong wanem, em i no bihainim yumi.',
        39: 'Tasol Jisas i tok, No ken tambuim em. Long wanem, i no gat man husat bai wokim wanpela mirakel long nem bilong Mi, husat i ken toktok nogut nating long Mi.',
        40: 'Long wanem, em husat i no birua long yumi i stap long sait bilong yumi.',
        41: '¶ Long wanem, husat man bai givim yupela wanpela kap wara bilong dring long nem bilong Mi, bilong wanem, yupela i bilong Kraist, tru tumas, Mi tokim yupela, pe bilong em bai no inap lus long em.',
        42: 'Na husat man bai bagarapim bel bilong wanpela bilong ol dispela liklik pikinini husat i bilip long Mi, em i gutpela moa long em long ol i hangamapim wanpela ston bilong krungutim wit nabaut long nek bilong em, na ol i tromoi em long biksi.',
        43: 'Na sapos han bilong yu i bagarapim bel bilong yu, katim dispela i go. Em i gutpela moa long yu long yu go insait long laip na hap bilong bodi bilong yu i bagarap, long taim yu gat tupela han yu go insait long hel, insait long dispela paia ol bai i no inap kilim i dai.',
        44: 'We liklik snek bilong ol i no inap dai, na ol i no inap kilim paia i dai.',
        45: 'Na sapos fut bilong yu i bagarapim bel bilong yu, katim dispela i go. Em i gutpela moa long yu long yu go lek nogut insait long laip, long taim yu gat tupela fut ol i tromoi yu i go insait long hel, insait long dispela paia ol i no inap kilim i dai.',
        46: 'We liklik snek bilong ol i no inap dai, na ol i no inap kilim paia i dai.',
        47: 'Na sapos ai bilong yu i bagarapim bel bilong yu, pulim dispela i kam ausait. Em i gutpela moa long yu long yu go insait long kingdom bilong God wantaim wanpela ai, long taim yu gat tupela ai ol i tromoi yu long hel paia.',
        48: 'We liklik snek bilong ol i no inap dai, na ol i no inap kilim paia i dai.',
        49: 'Long wanem, ol bai putim sol long olgeta wan wan wantaim paia, na ol bai putim sol long olgeta wan wan sakrifais wantaim sol.',
        50: 'Sol em i gutpela. Tasol sapos sol i bin lusim test bilong sol bilong en, yupela bai givim gutpela test long en wantaim wanem samting? Yupela i mas gat sol insait long yupela yet, na yupela i mas gat bel isi wanpela wantaim narapela.',
    },
    10: {
        1: '¶ Na Em i kirap long lusim dispela ples, na kam long ol hap arere bilong Judia long longwe sait bilong Jordan. Na ol manmeri i go long Em gen. Na, olsem Em i save mekim, Em i skulim ol gen.',
        2: 'Na ol Farisi i kam long Em, na askim Em, Em i orait long lo long wanpela man long rausim i go meri bilong em? Ol i traim Em.',
        3: 'Na Em i bekim na tokim ol, Moses i bin givim wanem tok strong long yupela?',
        4: 'Na ol i tok, Moses i larim em raitim wanpela pepa bilong brukim marit, na rausim em i go.',
        5: 'Na Jisas i bekim na tokim ol, Bikos bel bilong yupela i hat tru em i raitim dispela strongpela lo.',
        6: 'Tasol long stat bilong taim God i kamapim ol samting long nating God i wokim ol man na meri.',
        7: 'Long dispela as bai wanpela man i lusim papa na mama bilong em, na holimpas strong meri bilong em.',
        8: 'Na tupela bai stap wanpela bodi. Olsem tasol nau ol i no stap tupela moa, tasol wanpela bodi.',
        9: 'Olsem na wanem samting God i bin bungim wantaim, no ken larim man i brukim long tupela hap.',
        10: 'Na insait long haus ol disaipel bilong Em i askim Em gen long dispela wankain samting.',
        11: 'Na Em i tokim ol, Husat man bai rausim i go meri bilong em, na maritim narapela, i bagarapim marit long pamuk pasin i birua long em.',
        12: 'Na sapos wanpela meri bai rausim i go man bilong em, na maritim narapela, em i bagarapim marit long pamuk pasin.',
        13: '¶ Na ol i bringim ol yangpela pikinini long Em, inap long Em i ken tasim ol. Na ol disaipel bilong Em i hatim ol dispela husat i bringim ol.',
        14: 'Tasol taim Jisas i lukim dispela, Em i no amamas liklik, na Em i tokim ol, Larim ol liklik pikinini kam long Mi, na no ken tambuim ol. Long wanem, kingdom bilong God em i bilong ol kain olsem.',
        15: 'Tru tumas, Mi tokim yupela, Bai husat man i no kisim kingdom bilong God olsem wanpela liklik pikinini, em bai i no inap go insait long en.',
        16: 'Na Em i kisim ol i go antap long tupela han bilong Em, putim ol han bilong Em antap long ol, na blesim ol.',
        17: '¶ Na taim Em i go ausait long rot, i gat wanpela i ran i kam, na brukim skru long Em, na askim Em, Gutpela Tisa, mi bai mekim wanem inap long mi ken kisim laip i stap gut oltaim oltaim olsem samting papa i givim pikinini?',
        18: 'Na Jisas i tokim em, Bilong wanem yu kolim Mi gutpela? I no gat wanpela i gutpela, wanpela tasol, em i olsem, God.',
        19: 'Yu save long ol tok strong, No ken bagarapim marit long pamuk pasin, No ken kilim man, No ken stil, No ken stap giaman witnes, No ken stilim wantaim giaman, Givim ona long papa na mama bilong yu.',
        20: 'Na em i bekim na tokim Em, Tisa, olgeta dispela samting mi bin bihainim i stat taim mi yangpela i kam inap long nau.',
        21: 'Nau taim Jisas i lukim em Em i laikim em tru, na tokim em, Wanpela samting yu sot long en. Go long rot bilong yu, salim wanem samting yu gat, na givim long ol rabisman, na yu bai gat samting i dia tru antap long heven. Na kam, kisim diwai kros, na bihainim Mi.',
        22: 'Na em i pilim hevi long dispela toktok, na em i go wantaim bel i sori. Long wanem, em i gat planti samting tru em i holimpas.',
        23: 'Na Jisas i lukluk raun nabaut, na tokim ol disaipel bilong Em, Em bai hat tru long ol husat i gat planti mani samting long go insait long kingdom bilong God!',
        24: 'Na ol disaipel i kirap nogut long ol toktok bilong Em. Tasol Jisas i bekim tok gen, na tokim ol, Ol pikinini, em i hat moa long ol husat i putim bilip long ol mani samting long go insait long kingdom bilong God!',
        25: 'Em i isi moa long wanpela kemel i ken go namel long hul bilong nil bilong samap, long wanpela maniman i ken go insait long kingdom bilong God.',
        26: 'Na ol i kirap nogut ausait long skel, na toktok namel long ol yet, Husat nau God i ken kisim bek?',
        27: 'Na taim Jisas i lukluk long ol Em i tok, Wantaim ol man i no gat rot olgeta, tasol i no olsem wantaim God. Long wanem, wantaim God i gat rot long olgeta samting.',
        28: '¶ Nau Pita i stat long tokim Em, Harim, mipela i bin lusim olgeta samting, na mipela i bin bihainim Yu.',
        29: 'Na Jisas i bekim na tok, Tru tumas, Mi tokim yupela, I no gat wanpela man husat i bin lusim haus, o ol brata, o ol susa, o papa, o mama, o meri, o ol pikinini, o ol hap graun, bilong tingim Mi, na nem bilong gutnius,',
        30: 'Tasol long em bai kisim 100 taims nau long dispela taim, ol haus, na ol brata, na ol susa, na ol mama, na ol pikinini, na ol hap graun, wantaim ol taim bilong kisim hevi. Na long dispela skai na graun bilong kamap bihain, laip i stap gut oltaim oltaim.',
        31: 'Tasol planti husat i stap namba wan bai stap las. Na las bai stap namba wan.',
        32: '¶ Na ol i stap long rot i go antap long Jerusalem. Na Jisas i go paslain long ol. Na ol i kirap nogut tru. Na taim ol i bihainim Em, ol i pret. Na Em i kisim gen dispela twelpela, na stat long tokim ol long wanem ol samting bai kamap long Em,',
        33: 'I spik, Lukim, yumi go antap long Jerusalem. Na ol bai givim Pikinini Man bilong man i go long ol bikpris, na i go long ol man bilong rait. Na ol bai mekim Em lus long kot inap long dai, na ol bai givim Em long ol man i no Ju.',
        34: 'Na ol bai wokim pani long daunim Em, na ol bai wipim Em, na ol bai spetim Em, na ol bai kilim Em. Na long namba tri de Em bai kirap bek gen.',
        35: 'Na Jems na Jon, tupela pikinini man bilong Sebedi, i kam long Em, i spik, Tisa, mipela i gat laik long Yu ken mekim bilong helpim mipela wanem samting mipela bai gat laik.',
        36: 'Na Em i tokim ol, Yupela i gat laik long Mi ken mekim wanem samting bilong helpim yutupela?',
        37: 'Ol i tokim Em, Tok orait long mitupela long mitupela i ken sindaun, wanpela long han sut sait bilong Yu, na arapela long han kais sait bilong Yu, taim Yu stap long glori bilong Yu.',
        38: 'Tasol Jisas i tokim ol, Yutupela i no save long yutupela i askim wanem. Yutupela i ken dring long dispela kap Mi dring long en? Na kisim baptais wantaim dispela baptais Mi kisim baptais long en?',
        39: 'Na tupela i tokim Em, Mitupela ken. Na Jisas i tokim ol, Em i tru yutupela bai dring long dispela kap Mi dring long en. Na wantaim dispela baptais Mi kisim baptais long en yutupela bai kisim baptais wantaim dispela olgeta.',
        40: 'Tasol bilong sindaun long han sut sait bilong Mi na long han kais sait bilong Mi em i no bilong Mi long givim. Tasol God bai givim dispela long ol husat Em i redim dispela.',
        41: 'Na taim dispela tenpela i harim dispela, amamas bilong ol wantaim Jems na Jon i stat long stap bagarap planti.',
        42: 'Tasol Jisas i singautim ol i kam long Em, na tokim ol, Yupela save long ol husat ol i kaunim long bosim ol man i no Ju i hatwok long yusim namba antap long ol. Na ol bikman stret bilong ol i hatwok long yusim namba long bosim antap long ol.',
        43: 'Tasol em bai i no inap stap olsem namel long yupela. Tasol husat man bai stap bikman namel long yupela, bai stap wokman bilong yupela.',
        44: 'Na husat man bilong yupela bai stap nambawan tru, bai stap wokboi bilong olgeta.',
        45: 'Long wanem, yes, Pikinini Man bilong man i no kam long ol man i ken wokim wok long Em, tasol long wokim wok, na givim laip bilong Em wanpela pe bilong baim bek planti.',
        46: '¶ Na ol i kam long Jeriko. Na taim Em i go ausait long Jeriko wantaim ol disaipel bilong Em na bikpela namba bilong ol manmeri, aipas Bartimeas, pikinini man bilong Timeas, i sindaun klostu long sait bilong bikrot na pulim ol mani samting.',
        47: 'Na taim em i harim long em i Jisas bilong Nasaret, em i stat long singaut, na tok, Jisas, Yu Pikinini Man bilong Devit, soim pasin sori long mi.',
        48: 'Na planti i givim tok long em long em i mas pasim maus bilong em. Tasol em i singaut planti moa tru, Yu Pikinini Man bilong Devit, soim pasin sori long mi.',
        49: 'Na Jisas i sanap i stap, na tok strong long ol long singautim em. Na ol i singautim dispela aipas man, i spik long em, Stap wantaim gutpela bel isi, kirap. Em i singautim yu.',
        50: 'Na em, taim em i tromoi klos bilong em i go, i kirap, na kam long Jisas.',
        51: 'Na Jisas i bekim na tokim em, Yu gat laik long Mi ken mekim wanem long yu? Na aipas man i tokim Em, Bikpela, inap long mi ken kisim strong long lukluk.',
        52: 'Na Jisas i tokim Em, Go long rot bilong yu. Bilip tru bilong yu i bin mekim yu orait olgeta. Na wantu em i kisim strong long lukluk, na em i bihainim Jisas long rot.',
    },
    11: {
        1: '¶ Na taim ol i kam klostu long Jerusalem, long Betfagi na Betani, long maunten bilong ol Oliv, Em i salim tupela bilong ol disaipel bilong Em bilong go ausait,',
        2: 'Na Em i tokim tupela, Go long rot bilong yutupela i go insait long vilis i pas klostu long yupela. Na long taim stret long yupela i go insait long en, yupela bai lukim wanpela pikinini donki rop i pasim, we i no gat man i bin sindaun antap long en bipo. Lusim em, na bringim em.',
        3: 'Na sapos wanpela man i tokim yutupela, Bilong wanem yutupela i mekim dispela? Yupela bai tok long Bikpela i gat nid long em. Na kwiktaim em bai salim em i kam long hia.',
        4: 'Na tupela i go long rot bilong ol, na lukim wanpela pikinini donki rop i pasim klostu long dua ausait long wanpela ples we tupela rot i bung. Na ol i lusim em.',
        5: 'Na sampela bilong ol husat i sanap long dispela hap i tokim ol, Yutupela i mekim wanem, taim yupela i lusim pikinini donki?',
        6: 'Na tupela i tokim ol, yes, olsem Jisas i bin tok strong. Na ol i larim tupela i go.',
        7: 'Na tupela i bringim dispela pikinini donki long Jisas, na tromoi ol klos bilong ol antap long em. Na Em i sindaun antap long em.',
        8: 'Na planti i opim ol klos bilong ol long rot. Na ol arapela i katim daun ol han bilong diwai bilong ol diwai, na tromoi ol nabaut long rot.',
        9: 'Na ol husat i go paslain, na ol husat i kam bihain, i singaut, i spik, Hosana. Blesing i stap long Em husat i kam long nem bilong Bikpela.',
        10: 'Blesing i stap long kingdom bilong papa bilong yumi Devit, husat i kam long nem bilong Bikpela. Hosana i antap moa olgeta.',
        11: 'Na Jisas i go insait long Jerusalem, na insait long tempel. Na taim Em i bin lukluk raun nabaut long olgeta samting, na nau apinun tru i kamap, Em i go ausait i go long Betani wantaim dispela twelpela.',
        12: '¶ Na long de bihain, taim ol lusim Betani i kam, Em i hangre.',
        13: 'Na taim Em i lukim wanpela diwai fik i stap longwe i gat ol lip, Em i kam, sapos i ken kamap long Em i ken lukim wanpela samting antap long en. Na taim Em i kam long en, Em i no lukim wanpela arapela samting, ol lip tasol. Long wanem, taim bilong fik i no kamap yet.',
        14: 'Na Jisas i bekim na tokim dispela, I no gat man bai kaikai prut bilong yu bihain long nau inap long oltaim oltaim. Na ol disaipel bilong Em i harim dispela.',
        15: 'Na ol i kam long Jerusalem. Na Jisas i go insait long tempel, na stat long tromoi i go ausait ol man husat i salim na baim ol samting insait long tempel, na Em i tromoi i go daun ol tebol bilong ol man bilong senisim mani, na ol sia bilong ol husat i salim ol balus long mani.',
        16: 'Na Em i no gat laik long larim wanpela man i ken karim wanpela sospen samting i go namel long tempel.',
        17: 'Na Em i skulim ol, i spik i go long ol, Ating i yes long rait i stap pinis, Olgeta kantri bai kolim haus bilong Mi haus bilong prea? Tasol yupela i bin mekim dispela wanpela hul bilong ol stilman.',
        18: 'Na ol man bilong rait na ol bikpris i harim dispela, na ol i painim rot long ol i ken bagarapim Em olgeta olsem wanem. Long wanem, ol i pret long Em, bilong wanem, olgeta manmeri i kirap nogut long skul bilong Em.',
        19: 'Na taim apinun tru i kam pinis, Em i go ausait long biktaun.',
        20: 'Na long moning, taim ol i wokabaut klostu, ol i lukim dispela diwai fik i drai long rop daunbilo i kam antap.',
        21: 'Na Pita i bringim long tingting gen na tokim Em, Tisa, lukim, dispela diwai fik Yu bin toknogutim i go drai olgeta.',
        22: 'Na Jisas i bekim tok long ol, Yu mas gat bilip tru long God.',
        23: 'Long wanem, tru tumas, Mi tokim yupela, Long husat man bai tokim dispela maunten, Yu lusim hap i go, na God i ken tromoi yu long biksi, na bai em i no gat tupela tingting insait long bel bilong em, tasol em bai bilip long ol dispela samting, dispela em i tok, bai kamap olsem, em bai gat wanem samting em i tok.',
        24: 'Olsem na Mi tokim yupela, Wanem samting olgeta yupela i gat laik long en, taim yupela i beten, bilip long yupela bai kisim ol, na yupela bai kisim ol.',
        25: 'Na taim yupela i sanap na beten, lusim rong, sapos yupela i gat samting i birua long wanpela. Inap long Papa bilong yupela tu husat i stap long heven i ken lusim ol pasin bilong yupela bilong sakim lo.',
        26: 'Tasol sapos yupela i no lusim rong, Papa bilong yupela tu, husat i stap long heven, bai i no inap lusim ol pasin bilong yupela bilong sakim lo.',
        27: '¶ Na ol i kam gen long Jerusalem. Na taim Em i wokabaut insait long tempel, i gat ol bikpris i kam long Em, na ol man bilong rait, na ol lapun hetman,',
        28: 'Na ol i tokim Em, Yu kisim wanem namba bilong bosim inap long Yu mekim ol dispela samting? Na husat i givim dispela namba bilong bosim long Yu long mekim ol dispela samting?',
        29: 'Na Jisas i bekim na tokim ol, Mi bai askim yupela tu wanpela askim, na yupela bekim Mi, na Mi bai tokim yupela long Mi kisim wanem namba bilong bosim we na Mi wokim ol dispela samting.',
        30: 'Baptais bilong Jon, em i kam long heven, ol long ol man? Bekim Mi.',
        31: 'Na ol i wok long stretim tok wantaim ol yet, i spik, Sapos yumi bai tok, Long heven, Em bai tok, Bilong wanem nau yupela i no bin bilipim em?',
        32: 'Tasol sapos yumi bai tok, Long ol man. Ol i pret long ol manmeri. Long wanem, olgeta man i kaunim Jon, long em i tru em i wanpela profet.',
        33: 'Na ol i bekim na tokim Jisas, Mipela i no inap tokaut. Na Jisas i bekim tok long ol, Na tu Mi bai i no inap tokim yupela long Mi kisim wanem namba bilong bosim we long mekim ol dispela samting.',
    },
    12: {
        1: '¶ Na Em i stat long toktok long ol long ol tok piksa. Wanpela man i planim wanpela gaden wain, na putim wanpela banis nabaut long en, na digim ples bilong bikpela dram bilong krungutim wain, na wokim wanpela taua, na larim dispela long han bilong ol man bilong lukautim gaden, na em i go long wanpela longwe kantri.',
        2: 'Na long taim bilong en em i salim wanpela wokboi long ol man bilong lukautim gaden, inap long em i ken kisim kaikai bilong gaden wain long ol man bilong lukautim gaden.',
        3: 'Na ol i kisim em, na paitim paitim em, na salim em i go emti.',
        4: 'Na gen em i salim narapela wokboi long ol. Na long em ol i tromoi ol ston, na bagarapim em long het, na salim em i go taim ol i mekim pasin i givim bikpela sem long em.',
        5: 'Na gen em i salim narapela. Na ol i kilim em, na planti arapela. Sampela ol i paitim paitim, na sampela ol i kilim.',
        6: 'Olsem na taim em i gat wanpela pikinini man tasol i stap, pikinini i stap klostu tru long bel bilong em tru, em i salim em tu las long ol, i spik, Ol bai givim biknem long pikinini man bilong mi.',
        7: 'Tasol ol dispela man bilong lukautim gaden i toktok namel long ol yet, Dispela em i pikinini i kisim samting long papa. Kam, yumi kilim em, na samting papa i givim pikinini bai bilong yumi.',
        8: 'Na ol i kisim em, na kilim em i dai, na tromoi em i go ausait long gaden wain.',
        9: 'Olsem na bikman bilong dispela gaden wain bai mekim wanem? Em bai kam na bagarapim olgeta ol dispela man bilong lukautim gaden, na em bai givim gaden wain i go long ol arapela.',
        10: 'Na ating i yes long yupela i bin ritim dispela rait bilong God, Dispela ston ol man bilong wokim haus i bin tok nogat olgeta long en em i kamap het bilong kona,',
        11: 'Dispela em i wok Bikpela i mekim, na long ai bilong mipela em i wok i mekim mipela tingting planti?',
        12: 'Na ol i painim rot long holimpas Em, tasol ol i pret long ol manmeri. Long wanem, ol i save long Em i bin toktok long dispela tok piksa i birua long ol. Na ol i lusim Em, na go long rot bilong ol.',
        13: '¶ Na ol i salim long Em sampela bilong ol Farisi na bilong ol lain bilong Herot, bilong holimpas Em insait long ol toktok bilong Em.',
        14: 'Na taim ol i kam pinis, ol i tokim Em, Tisa, mipela save long Yu stap trupela, na Yu no wari long tingting bilong wanpela man. Long wanem, Yu no tingting planti long namba bilong ol man, tasol Yu skulim ol manmeri long rot bilong God insait long tok tru. Em i orait long lo long givim takis mani long Sisa, o nogat?',
        15: 'Mipela bai givim, o mipela bai i no inap givim? Tasol Em, taim Em i save long pasin bilong tupela bel bilong ol, i tokim ol, Bilong wanem yupela i traim Mi? Bringim Mi wanpela peni, inap long Mi ken lukim.',
        16: 'Na ol i bringim. Na Em i tokim ol, Dispela piksa na rait ol i sapim em i bilong husat? Na ol i tokim Em, Bilong Sisa.',
        17: 'Na Jisas i bekim na tokim ol, Bekim long Sisa ol dispela samting i bilong Sisa, na long God ol dispela samting i bilong God. Na ol i tingting planti long Em.',
        18: '¶ Nau ol Sadyusi i kam long Em, husat i tok i no gat kirap bek long dai. Na ol i askim Em, i spik,',
        19: 'Tisa, Moses i raitim long mipela, Sapos brata bilong wanpela man i dai, na lusim meri bilong em bihain long em, na em i no gat sampela pikinini, long brata bilong em i mas kisim meri bilong em, na kirapim tumbuna pikinini long brata bilong em.',
        20: 'Nau i gat sevenpela brata. Na namba wan i kisim wanpela meri, na taim em i dai, em i no gat pikinini.',
        21: 'Na namba tu i kisim meri, na dai, na tu em i no gat wanpela pikinini. Na namba tri i wankain olsem.',
        22: 'Na dispela sevenpela i bin kisim meri, na ol i no gat pikinini. Las long olgeta, dispela meri i dai tu.',
        23: 'Olsem na long kirap bek long dai, taim ol bai kirap bek, em bai meri bilong husat bilong ol? Long wanem, sevenpela i bin maritim em.',
        24: 'Na Jisas i bekim na tokim ol, Olsem na ating i yes long yupela i paul, bilong wanem, yupela i no save long rait bilong God, na tu pawa bilong God?',
        25: 'Long wanem, taim ol bai kirap bek long dai, ol i no marit, na tu ol i no givim ol long marit. Tasol ol i stap olsem ol ensel husat i stap long heven.',
        26: 'Na long sait bilong ol daiman, long ol i kirap bek, ating i yes long yupela i bin ritim long buk bilong Moses, long God i tokim em long liklik bus olsem wanem, i spik, Mi stap God bilong Ebraham, na God bilong Aisak, na God bilong Jekop?',
        27: 'Em i no God bilong ol daiman, tasol God bilong ol man i stap laip. Olsem na yupela i paul tru.',
        28: '¶ Na wanpela bilong ol man bilong rait i kam, na taim em i harim ol i wok long stretim tok wantaim, na taim em i kisim save long Em i bin bekim ol gutpela, em i askim Em, Wanem tok strong em i namba wan bilong olgeta?',
        29: 'Na Jisas i bekim em, Namba wan bilong olgeta bilong ol tok strong em, Harim, O Isrel. Bikpela, God bilong yumi, em i wanpela Bikpela.',
        30: 'Na yu mas laikim tru Bikpela, God bilong yu, wantaim olgeta bel bilong yu, na wantaim olgeta tewel bilong yu, na wantaim olgeta tingting bilong yu, na wantaim olgeta strong bilong yu. Dispela em i namba wan tok strong.',
        31: 'Na namba tu em i wankain, em i dispela, Yu mas laikim tru man i stap klostu long yu olsem yu laikim yu yet. I no gat arapela tok strong i winim dispela tupela.',
        32: 'Na dispela man bilong rait i tokim Em, Gutpela, Tisa, Yu bin tok tru. Long wanem, i gat wanpela God. Na i no gat wanpela arapela, Em tasol.',
        33: 'Na bilong laikim Em tru wantaim olgeta bel, na wantaim olgeta save, na wantaim olgeta tewel, na wantaim olgeta strong, na long laikim tru man i stap klostu long em olsem em laikim em yet, em i moa long olgeta ofa i kuk olgeta na ol sakrifais.',
        34: 'Na taim Jisas i luksave long em i yusim save gut na bekim tok, Em i tokim em, Yu no stap longwe long kingdom bilong God. Na bihain long dispela i no gat man i gat laik long askim Em long wanpela askim.',
        35: '¶ Na Jisas i bekim na tok, taim Em i skulim ol manmeri long tempel, Ol man bilong rait i tok olsem Kraist em i Pikinini Man bilong Devit olsem wanem?',
        36: 'Long wanem, Devit em yet i toktok long wok bilong Holi Spirit, BIKPELA i tokim Bikpela bilong mi, Yu sindaun long han sut sait bilong Mi, inap long Mi mekim ol birua bilong Yu kamap liklik sia bilong putim lek bilong Yu.',
        37: 'Olsem na Devit em yet i kolim Em Bikpela. Na olsem wanem nau Em i pikinini man bilong em? Na ol manmeri nating i harim Em wantaim amamas.',
        38: 'Na Em i tokim ol long skul bilong Em, Lukaut gut long ol man bilong rait, husat i laikim tru long go long ol longpela klos, na laikim tru ol tok gude long ol ples maket,',
        39: 'Na ol nambawan sia long ol sinagog, na ol rum i antap moa olgeta long ol bikpela kaikai,',
        40: 'Husat i kaikai olgeta ol haus bilong ol meri man bilong ol i dai pinis, na long wanpela bel i no trupela ol i wokim ol longpela prea. Ol dispela bai kisim pe nogut bilong kot i bikpela moa.',
        41: '¶ Na Jisas i sindaun pas klostu long bakstua bilong ol samting i dia tru, na lukim long ol manmeri i tromoi mani i go insait long bakstua bilong ol samting i dia tru olsem wanem. Na planti husat i ol maniman i tromoi planti i go insait.',
        42: 'Na wanpela rabismeri man bilong em i dai pinis i kam, na em i tromoi tupela mait i go insait, dispela i mekim wanpela fating.',
        43: 'Na Em i singautim ol disaipel bilong Em i kam long Em, na tokim ol, Tru tumas, Mi tokim yupela, Long dispela rabismeri man bilong em i dai pinis i bin tromoi moa insait, long olgeta ol husat i bin tromoi insait long bakstua bilong ol samting i dia tru.',
        44: 'Long wanem, ol olgeta i bin tromoi bilong ol planti moa yet bilong ol. Tasol meri i bin tromoi bilong ol nid bilong em olgeta em i gat, yes, olgeta samting bilong em.',
    },
    13: {
        1: '¶ Na taim Em i go ausait long tempel, wanpela bilong ol disaipel bilong Em i tokim Em, Tisa, lukim wanem kain ol ston na wanem ol haus i stap long hia!',
        2: 'Na Jisas i bekim tok long em, Yu lukim ol dispela bikpela haus? Bai i no gat wanpela ston i stap yet antap long narapela, long ol bai i no inap tromoi i go daun.',
        3: 'Na taim Em i sindaun long maunten bilong ol Oliv pas klostu long tempel, Pita na Jems na Jon na Andrew i askim Em ol yet tasol,',
        4: 'Tokim mipela, ol dispela samting bai stap wanem taim? Na mak bilong taim bilong olgeta dispela samting bai i kamap pinis em bai wanem?',
        5: '¶ Na Jisas i bekim tok long ol na stat long tok, Was gut, nogut wanpela man i giamanim yupela.',
        6: 'Long wanem, planti bai kam long nem bilong Mi, i spik, Mi stap Kraist. Na ol bai giamanim planti.',
        7: 'Na taim yupela bai harim long ol bikpela pait na ol tok win bilong ol bikpela pait, yupela i no ken pilim wari. Long wanem, ol kain samting i mas i gat nid long stap. Tasol pinis bai i no inap stap yet.',
        8: 'Long wanem, kantri bai kirap i birua long kantri, na kingdom i birua long kingdom. Na bai i gat ol guria long kain kain ples, na bai i gat ol bikpela taim hangre na ol trabel. Ol dispela samting em ol stat bilong ol bel hevi.',
        9: 'Tasol yupela was gut long yupela yet. Long wanem, ol bai givim yupela i go long ol kaunsil. Na insait long ol sinagog ol bai paitim paitim yupela. Na ol bai bringim yupela long ai bilong ol hetman na ol king bilong tingim Mi, bilong wanpela testimoni i birua long ol.',
        10: 'Na yupela i mas mekim gutnius long kamap ples klia namel long olgeta kantri pastaim.',
        11: 'Tasol taim ol bai bringim yupela, na givim yupela i go, no ken tingting liklik bipotaim long yupela bai toktok wanem, na tu yupela i no ken tingting strong pastaim. Tasol wanem samting Em i givim yupela long dispela aua, dispela yupela bai toktok. Long wanem, em i no yupela husat i toktok, tasol Holi Spirit.',
        12: 'Nau brata bai givim brata long han bilong birua long dai, na papa pikinini man. Na ol pikinini bai kirap na birua long ol papamama bilong ol, na ol bai mekim ol i dai.',
        13: 'Na olgeta man bai hetim yupela bilong tingim nem bilong Mi. Tasol em husat bai stap strong yet inap long pinis, em yet God bai kisim bek.',
        14: '¶ Tasol taim yupela bai lukim dispela sting samting bilong taim bilong stap nating olgeta, dispela profet Danyel i toktok long en, taim em i sanap we i no gutpela long em long sanap, (larim em husat i ritim kisim save,) orait larim ol husat i stap long Judia ranawe i go long ol maunten.',
        15: 'Na larim em husat i stap antap long antap bilong haus i no ken go daun insait long haus, na tu go insait long en, long kisim wanpela samting ausait long haus bilong em.',
        16: 'Na larim em husat i stap long bikpela gaden i no ken tanim i go bek gen bilong kisim klos bilong em.',
        17: 'Tasol tok lukaut i go long ol husat i gat bel, na long ol husat i givim susu long ol dispela de!',
        18: 'Na yupela i mas beten long taim bilong ranawe bilong yupela i no stap long taim bilong bikpela kol.',
        19: 'Long wanem, long ol dispela de taim bilong kisim hevi bai stap, kain olsem i no bin stap long stat bilong ol dispela samting God i kamapim long nating inap long dispela taim nau, na tu em bai i no inap stap.',
        20: 'Na sapos long Bikpela i no bin sotim ol dispela de, i no gat wanpela bodi i stap yet long kisim bek. Tasol bilong tingim ol man God i bin makim, husat Em i bin makim, Em i bin sotim ol de.',
        21: 'Na nau sapos wanpela man bai tokim yupela, Harim, Kraist i stap hia, o, harim, Em i stap long hap. No ken bilipim em.',
        22: 'Long wanem, ol giaman Kraist na ol giaman profet bai kirap, na ol bai soim ol mak na ol samting bilong winim tingting, bilong grisim, sapos i gat rot, yes, ol man God i makim.',
        23: 'Tasol yupela was gut. Lukim, Mi bin toksave pastaim long yupela long olgeta samting.',
        24: '¶ Tasol long ol dispela de, bihain long dispela taim bilong bikpela hevi, san bai go tudak, na mun bai i no inap givim lait bilong em,',
        25: 'Na ol sta bilong heven bai pundaun, na ol dispela pawa i stap long heven bai seksek.',
        26: 'Na nau bai ol i lukim Pikinini Man bilong man i kam long ol klaut wantaim bikpela pawa na glori.',
        27: 'Na nau bai Em i salim ol ensel bilong Em, na ol bai bungim wantaim ol man God i makim bilong Em i kam long dispela fopela win, i stat long las hap bilong dispela graun i go long las hap bilong heven.',
        28: '¶ Nau lainim wanpela tok piksa bilong diwai fik. Taim han bilong em i no strong yet, na em i putim ol lip i go ausait, yupela save long taim bilong biksan i kam klostu.',
        29: 'Olsem tasol yupela long wankain pasin, taim yupela bai lukim ol dispela samting i kamap olsem, yupela i ken save long em i klostu, yes, long ol dua.',
        30: 'Tru tumas, Mi tokim yupela, long dispela lain tumbuna bai i no inap pinis, inap long olgeta dispela samting i kamap pinis.',
        31: 'Heven na dispela graun bai pinis olgeta. Tasol ol toktok bilong Mi bai i no inap pinis olgeta.',
        32: 'Tasol long dispela de na dispela aua i no gat man i save, nogat, i no ol ensel husat i stap long heven, na tu Pikinini Man, Papa tasol.',
        33: 'Yupela was gut, was na beten. Long wanem, yupela i no save long wanem taim dispela bai kamap.',
        34: 'Long wanem, Pikinini Man bilong man em i olsem wanpela man i go long wanpela longwe wokabaut, husat i lusim haus bilong em, na givim namba bilong bosim long ol wokboi bilong em, na long olgeta wan wan man wok bilong em, na em i tok strong long wasman bilong dua long was.',
        35: 'Olsem na yupela mas was. Long wanem, yupela i no save long taim bosman bilong haus bai kam, long apinun tru, o long belo biknait, o long taim kakaruk man i singaut, o long moning.',
        36: 'Nogut taim Em i kam wantu Em i lukim yupela i slip.',
        37: 'Na wanem samting Mi tokim yupela Mi tokim olgeta, Was.',
    },
    14: {
        1: '¶ Bihain long tupela de em bikpela kaikai bilong pasova, na bilong bret i no gat yis. Na ol bikpris na ol man bilong rait i painim rot long ol i ken kisim Em long trik pasin olsem wanem, na mekim Em long dai.',
        2: 'Tasol ol i tok, I no ken long de bilong bikpela kaikai, nogut i gat wanpela bikpela paul nabaut bilong ol manmeri.',
        3: 'Na taim Em i stap long Betani long haus bilong lepraman Saimon, taim Em i sindaun long kaikai, i gat i kam wanpela meri taim em i gat bokis alabasta bilong wel i gat marasin bilong spaiknard i dia tumas tru. Na em i brukim dispela bokis, na kapsaitim dispela antap long het bilong Em.',
        4: 'Na i gat sampela husat i gat bel nogut insait long ol yet, na tok, Bilong wanem em i tromoi nating dispela wel i gat marasin?',
        5: 'Long wanem, yumi bin inap long salim dispela long moa long 300 pens, na yumi bin inap long givim dispela long ol rabisman. Na ol i tok baksait i birua long em.',
        6: 'Na Jisas i tok, Larim em i stap. Bilong wanem yupela i givim wari long em? Em i bin wokim wanpela gutpela wok antap long Mi.',
        7: 'Long wanem, yupela i gat ol rabisman wantaim yupela olgeta taim, na wanem taim tru yupela i gat laik yupela i ken mekim gut long ol. Tasol yupela bai i no inap gat Mi olgeta taim.',
        8: 'Em i bin mekim wanem samting em i ken mekim. Em i kam pastaim bilong makim bodi bilong Mi wantaim wel bilong planim.',
        9: 'Tru tumas, Mi tokim yupela, Long wanem hap olgeta ol bai autim dispela gutnius namel long olgeta hap bilong dispela graun olgeta, dispela tu long em i bin mekim bai ol i toktok long en bilong wanpela samting bilong holim tingting long em.',
        10: 'Na Judas Iskariot, wanpela bilong dispela twelpela, i go long ol bikpris, bilong putim Em long han bilong ol.',
        11: 'Na taim ol i harim dispela, ol i amamas, na ol i wokim promis long givim em mani. Na em i painim rot i fit long em i ken putim Em long han bilong ol.',
        12: '¶ Na namba wan de bilong bret i no gat yis, taim ol i kilim pasova, ol disaipel bilong Em i tokim Em, Yu gat laik long mipela i go we na redim inap long Yu ken kaikai dispela pasova?',
        13: 'Na Em i salim tupela bilong ol disaipel bilong Em i go ausait, na tokim tupela, Yutupela go insait long biktaun, na long dispela hap bai wanpela man i bungim yupela husat i karim wanpela jak wara. Bihainim em.',
        14: 'Na long wanem hap olgeta em bai go insait, yupela tokim papa bilong dispela haus, Tisa i tok, Rum bilong stap aninit long lukaut bilong yu i stap we, we Mi bai kaikai dispela pasova wantaim ol disaipel bilong Mi?',
        15: 'Na em bai soim yutupela wanpela traipela rum antap i gat ol samting pinis na i redi. Long dispela hap redim bilong yumi.',
        16: 'Na tupela disaipel bilong Em i go ausait, na kam insait long biktaun, na lukim olsem Em i bin tokim ol. Na ol i redim pasova.',
        17: 'Na long apinun tru Em i kam wantaim dispela twelpela.',
        18: 'Na taim ol i bin sindaun na kaikai, Jisas i tok, Tru tumas, Mi tokim yupela, Wanpela bilong yupela husat i kaikai wantaim Mi bai putim Mi long han bilong birua.',
        19: 'Na ol i stat long stap pulap long bel i pilim hevi, na long tokim Em wanpela i bihain long narapela, Em mi? Na narapela i tok, Em mi?',
        20: 'Na Em i bekim na tokim ol, Em i wanpela bilong dispela twelpela, husat i putim bret liklik wantaim Mi insait long dis.',
        21: 'Em i tru Pikinini Man bilong man i go, olsem rait i stap pinis long sait bilong Em. Tasol tok lukaut i go long dispela man husat i putim Pikinini Man bilong man long han bilong birua! Em i gutpela long dispela man sapos mama i no bin karim em.',
        22: 'Na taim ol i bin kaikai, Jisas i kisim bret, na blesim, na brukim, na givim long ol, na tok, Kisim, kaikai. Dispela em i bodi bilong Mi.',
        23: 'Na Em i kisim kap, na taim Em i bin givim tok tenkyu, Em i givim long ol. Na ol olgeta i bin dring long en.',
        24: 'Na Em i tokim ol, Dispela em i blut bilong Mi bilong nupela testamen, dispela i kapsait bilong helpim planti.',
        25: 'Tru tumas, Mi tokim yupela, Mi bai i no inap dring moa long prut bilong rop wain, inap long dispela de long Mi dringim dispela nupela insait long kingdom bilong God.',
        26: 'Na taim ol i bin singim wanpela song bilong lotu, ol i go ausait i go long maunten bilong ol Oliv.',
        27: 'Na Jisas i tokim ol, Bel bilong yupela olgeta bai bagarap bilong tingim Mi long dispela nait. Long wanem, rait i stap pinis, Mi bai paitim wasman bilong sipsip, na ol sipsip bai bruk nabaut.',
        28: 'Tasol bihain long Mi kirap bek, Mi bai go paslain long yupela i go long Galili.',
        29: 'Tasol Pita i tokim Em, Maski long bel bilong olgeta bai bagarap, tasol mi bai i no inap.',
        30: 'Na Jisas i tokim em, Tru tumas, Mi tokim yu, Long dispela de, yes, long dispela nait, bipo long kakaruk man bai singaut tupela taim, yu bai tok nogat long Mi tripela taim.',
        31: 'Tasol em i tok strong nogut tru moa, Sapos mi bai dai wantaim Yu, mi bai i no inap tru long tok nogat long Yu. Wankain olsem tu ol olgeta i tok.',
        32: '¶ Na ol i kam long wanpela ples, dispela nem bilong en em Getsemani. Na Em i tokim ol disaipel bilong Em, Yupela sindaun hia, taim Mi bai beten.',
        33: 'Na Em i kisim wantaim Em Pita na Jems na Jon, na Em i stat long kirap nogut tru strong tru, na long stap bel hevi tru.',
        34: 'Na Em i tokim tripela, Tewel bilong Mi i pulap long bel i pilim hevi planti moa yet i go inap long dai. Yupela stap yet hia, na was.',
        35: 'Na Em i go antap liklik, na pundaun long graun, na beten long, sapos em i gat rot, dispela aua i ken abrusim Em.',
        36: 'Na Em i tok, Aba, Papa, i gat rot long olgeta samting long Yu. Kisim dispela kap i abrusim Mi. Tasol, i no wanem samting Mi laik, tasol wanem samting Yu laik.',
        37: 'Na Em i kam, na lukim ol i slip, na Em i tokim Pita, Saimon, yu slip? Ating i yes long yu inap was wanpela aua?',
        38: 'Yupela was na beten, nogut yupela i go insait long traim. Tru tumas, spirit i redi, tasol bodi i no gat strong.',
        39: 'Na gen Em i go, na beten, na toktok long ol wankain toktok.',
        40: 'Na taim Em i go bek, Em i lukim ol i slip gen, (long wanem, ol ai bilong ol i hevi,) na tu ol i no save long ol bai bekim Em olsem wanem.',
        41: 'Na Em i kam namba tri taim, na tokim ol, Slip nau, na kisim malolo bilong yupela. Em inap, aua i kam pinis. Lukim, ol i putim Pikinini Man bilong man long han bilong ol sinman.',
        42: 'Kirap, yumi go. Harim, em husat i putim Mi long han bilong birua i klostu.',
        43: '¶ Na wantu, taim Em i toktok yet, Judas i kam, wanpela bilong dispela twelpela, na wantaim em wanpela traipela lain tru wantaim ol bainat na ol stik bilong pait, i kam long ol bikpris na ol man bilong rait na ol lapun hetman.',
        44: 'Na em husat i putim Em long han bilong birua i bin givim ol wanpela mak, i spik, Husat Man mi bai givim kis, Em Yet em Em. Kisim Em, na bringim Em i go gut.',
        45: 'Na long taim stret long em i kam, em i go kwiktaim long Em, na tok, Tisa, tisa, na givim kis long Em.',
        46: 'Na ol i putim ol han bilong ol antap long Em, na kisim Em.',
        47: 'Na wanpela bilong ol husat i sanap klostu i pulim bainat, na paitim wanpela wokboi bilong hetpris, na katim i go ia bilong em.',
        48: 'Na Jisas i bekim na tokim ol, Ating yupela i kam ausait, olsem bilong birua long wanpela stilman, wantaim ol bainat na wantaim ol stik bilong pait bilong kisim Mi?',
        49: 'Mi stap olgeta wan wan de wantaim yupela insait long tempel taim Mi skulim ol manmeri, na yupela i no kisim Mi. Tasol ol rait bilong God i mas kamap pinis.',
        50: 'Na ol olgeta i givim baksait long Em, na ranawe.',
        51: 'Na i gat i bihainim Em wanpela yangpela man, na em i gat wanpela naispela laplap em i tromoi nabaut long skin nating bodi bilong em. Na ol yangpela man i holimpas em.',
        52: 'Na em i lusim dispela naispela laplap, na ranawe long ol skin nating.',
        53: '¶ Na ol i bringim Jisas i go long hetpris. Na wantaim em olgeta bikpris na ol lapun hetman na ol man bilong rait i bung.',
        54: 'Na Pita i bihainim Em longwe tru, yes, i go insait long haus king bilong hetpris. Na em i sindaun wantaim ol wokboi, na hatim skin bilong em yet long paia.',
        55: 'Na ol bikpris na olgeta dispela kaunsil i painim wanpela witnes i birua long Jisas bilong mekim Em long dai. Na ol i no painim wanpela pinis.',
        56: 'Long wanem, planti i givim giaman witnes i birua long Em, tasol ol witnes bilong ol i no wanbel wantaim.',
        57: 'Na i gat sampela i kirap, na givim giaman witnes i birua long Em, i spik,',
        58: 'Mipela i harim Em tok, Mi bai bagarapim dispela tempel olgeta, dispela ol i wokim wantaim ol han, na insait long tripela de Mi bai wokim narapela i no gat ol han i wokim.',
        59: 'Tasol olsem tu ol witnes bilong ol i no bin wanbel wantaim.',
        60: 'Na hetpris i sanap namel long ol, na askim Jisas, i spik, Yu no bekim wanpela samting? Em wanem samting ol dispela i witnes i birua long Yu?',
        61: 'Tasol Em i pasim maus bilong Em, na Em i no bekim wanpela samting. Na gen hetpris i askim Em, na tokim Em, Yu stap dispela Kraist, Pikinini Man bilong Man i Stap Blesing?',
        62: 'Na Jisas i tok, Em Mi. Na yupela bai lukim Pikinini Man bilong man i sindaun long han sut sait bilong pawa, na kam long ol klaut bilong heven.',
        63: 'Nau hetpris i brukim klos bilong em, na tok, Yumi gat wanem nid long sampela witnes moa?',
        64: 'Yupela i bin harim dispela tok bilas. Yupela i ting wanem? Na ol olgeta i mekim Em i lus long kot long Em i gat asua inap long dai.',
        65: 'Na sampela i stat long spetim Em, na long karamapim pes bilong Em, na long paitim Em, na long tokim Em, Autim tok profet. Na ol wokboi i bin paitim Em wantaim ol pes bilong ol han bilong ol.',
        66: '¶ Na taim Pita i stap aninit long haus king, i gat wanpela i kam bilong ol yangpela meri bilong hetpris.',
        67: 'Na taim em i lukim Pita i hatim skin bilong em yet, em i lukluk long em, na tok, Na yu tu i bin stap wantaim Jisas bilong Nasaret.',
        68: 'Tasol Em i tok nogat, i spik, Mi no save, na tu mi no klia long wanem samting yu toktok. Na em i go ausait long veranda. Na kakaruk man i singaut.',
        69: 'Na wanpela yangpela meri i lukim em gen, na stat long tokim ol husat i sanap klostu, Dispela em i wanpela bilong ol.',
        70: 'Na em i tok nogat long en gen. Na liklik taim bihain, ol husat i sanap klostu i tok gen long Pita, Tru tumas, yu stap wanpela bilong ol. Long wanem, yu stap wanpela man Galili, na pasin bilong toktok bilong yu i wanbel long dispela.',
        71: 'Tasol em i stat long tok nogut na long wokim strongpela promis, i spik, Mi no save long dispela Man husat yupela toktok long En.',
        72: 'Na namba tu taim kakaruk man i singaut. Na Pita i bringim long tingting gen dispela tok Jisas i tokim em, Bipo long kakaruk man bai singaut tupela taim, yu bai tok nogat long Mi tripela taim. Na taim em i tingting long en, em i krai tru.',
    },
    15: {
        1: '¶ Na kwiktaim long moningtaim ol bikpris i holim wanpela bung bilong painim tingting wantaim ol lapun hetman na ol man bilong rait na dispela kaunsil olgeta, na ol i pasim Jisas, na karim Em i go, na givim Em long Pailat.',
        2: 'Na Pailat i askim Em, Yu stap King bilong ol Ju? Na Em i bekim tok long em, Yu tok olsem.',
        3: 'Na ol bikpris i sutim tok long Em long planti samting. Tasol Em i no bekim wanpela samting.',
        4: 'Na Pailat i askim Em gen, i spik, Yu no bekim wanpela samting? Lukim hamas samting ol i witnes i birua long Yu.',
        5: 'Tasol yet Jisas i no bekim wanpela samting, inap long Pailat i tingting planti.',
        6: 'Nau long dispela bikpela kaikai em i lusim long ol wanpela kalabusman, husat man ol i gat laik.',
        7: 'Na i gat wanpela husat nem bilong en em Barabas, husat i slip pas wantaim ol husat i bin wokim bikpela kirap long birua long gavman wantaim em, husat i bin kilim man insait long dispela bikpela kirap long birua long gavman.',
        8: 'Na dispela bikpela lain tru i stat long singaut strong long askim em long mekim olsem em i bin mekim oltaim long ol.',
        9: 'Tasol Pailat i bekim ol, i spik, Yupela i gat laik long Mi lusim long yupela King bilong ol Ju?',
        10: 'Long wanem, em i save long ol bikpris i bin gat mangal tingting na givim Em long em.',
        11: 'Tasol ol bikpris i muvim ol manmeri, long em i mobeta long em i ken lusim Barabas i go long ol.',
        12: 'Na Pailat i bekim na tok gen long ol, Yupela i gat laik nau long mi bai mekim wanem long Em husat yupela i kolim King bilong ol Ju?',
        13: 'Na ol i singaut gen, Nilim Em long diwai kros.',
        14: 'Nau Pailat i tokim ol, Bilong wanem, Em i bin mekim wanem pasin nogut? Na ol i singaut planti moa yet, Nilim Em long diwai kros.',
        15: '¶ Na olsem tasol Pailat, taim em i gat laik long mekim ol manmeri long tok em inap, i givim Barabas long ol, na givim Jisas, taim em i bin wipim Em, long ol i ken nilim Em long diwai kros.',
        16: 'Na ol soldia i bringim Em i go insait long bikpela rum ol i kolim Pretoriam. Na ol i singautim olgeta lain soldia bilong bung wantaim.',
        17: 'Na ol i putim purpelpela klos long Em, na wokim wanpela hat king bilong ol rop i gat nil, na putim dispela nabaut long het bilong Em,',
        18: 'Na ol i stat long tok gude long Em, Gude, King bilong ol Ju!',
        19: 'Na ol i paitim Em long het wantaim wanpela rit, na ol i bin spet antap long Em, na taim ol i lindaunim ol skru bilong ol ol i lotuim Em.',
        20: 'Na taim ol i bin wokim pani long daunim Em pinis, ol i rausim dispela purpelpela long Em, na putim klos bilong Em Yet long Em, na bringim Em ausait bilong nilim Em long diwai kros.',
        21: 'Na ol i pulim strong wanpela man Sairini Saimon, husat i wokabaut klostu, taim em i kam ausait long hap i no gat planti man, papa bilong Aleksandar na Rufas, long karim diwai kros bilong Em.',
        22: '¶ Na ol i bringim Em i go long ples Golgata, dispela em, taim ol i tanim, Ples bilong bun bilong het.',
        23: 'Na ol i givim Em bilong dring wain ol i abusim wantaim mur. Tasol Em i no kisim dispela.',
        24: 'Na taim ol i bin nilim Em long diwai kros, ol i brukim ol klos bilong Em, taim ol i tromoi satu antap long ol, long olgeta wan wan man bai kisim wanem.',
        25: 'Na em i namba tri aua, na ol i nilim Em long diwai kros.',
        26: 'Na rait ol i sapim bilong sutim tok long Em ol i raitim antap, KING BILONG OL JU.',
        27: 'Na wantaim Em ol i nilim tupela stilman long diwai kros, wanpela long han sut bilong Em, na arapela long han kais.',
        28: 'Na rait bilong God i kamap pinis, dispela i tok, Na ol i kaunim Em wantaim ol man bilong kalapim lo.',
        29: 'Na ol husat i wokabaut klostu i daunim Em tru, na seksekim ol het bilong ol, na tok, Ah, Yu husat i bagarapim tempel olgeta, na wokim dispela gen long tripela de,',
        30: 'Kisim bek Yu Yet, na kam daun long diwai kros.',
        31: 'Wankain olsem tu ol bikpris i wokim pani long daunim namel long ol yet wantaim ol man bilong rait, Em i kisim bek ol arapela. Em i no inap long kisim bek Em Yet.',
        32: 'Larim Kraist, King bilong Isrel, kam daun nau long diwai kros, inap long yumi ken lukim na bilipim. Na tupela husat ol i nilim long diwai kros wantaim Em i sutim tok nogut long Em.',
        33: '¶ Na taim namba sikis aua i kam, i gat tudak antap long dispela hap olgeta inap long namba nain aua.',
        34: 'Na long namba nain aua Jisas i singaut wantaim bikpela nek, i spik Eloi, Eloi, lama sabaktani? Dispela em, taim ol i tanim, God bilong Mi, God bilong Mi, bilong wanem Yu bin givim baksait long Mi?',
        35: 'Na sampela husat i sanap klostu, taim ol i harim dispela, i tok, Lukim, em i singautim Ilaias.',
        36: 'Na wanpela i ran na pulimapim wanpela spans i pulap long vinega, na putim dispela long wanpela rit, na givim Em bilong dring, i spik, Larim i stap. Yumi lukim long Ilaias bai kam long kisim Em i go daun o nogat.',
        37: 'Na Jisas i singaut wantaim bikpela nek, na lusim spirit bilong Em.',
        38: 'Na laplap bilong tempel i bruk long tupela hap i stat long antap i go daunbilo olgeta.',
        39: 'Na taim dispela kepten bilong 100 soldia, husat i sanap pas klostu long Em, i lukim long Em i singaut olsem, na lusim spirit bilong Em, em i tok, Tru tumas, dispela Man em i Pikinini Man bilong God.',
        40: 'I gat tu ol meri i stap longwe na lukluk. Namel long husat em Maria Magdala, na Maria, mama bilong liklik Jems na bilong Joses, na Salomi,',
        41: '(Husat tu, taim Em i stap long Galili, i bihainim Em, na wokim wok long Em,) na planti arapela meri husat i kam antap wantaim Em long Jerusalem.',
        42: '¶ Na nau taim apinun tru i kam pinis, bikos em i de bilong redim, em i olsem, de bipo long sabat,',
        43: 'Josep bilong Arimatia, wanpela man bilong givim tok helpim i gat ona, husat tu i wetim kingdom bilong God, i kam, na go insait long Pailat wantaim pasin bilong i no pret, na em i laik tru long kisim daibodi bilong Jisas.',
        44: 'Na Pailat i tingting planti long sapos Em i bin dai pinis. Na taim em i singautim long em dispela kepten bilong 100 soldia, em i askim em long Em i bin stap daiman sampela taim liklik o nogat.',
        45: 'Na taim em i save long en long kepten bilong 100 soldia, em i givim daibodi long Josep.',
        46: 'Na em i baim ol laplap i naispela tru, na kisim Em i go daun, na tantanim Em insait long naispela laplap, na slipim Em insait long dispela matmat ol man i katim ausait long ston, na tantanim wanpela ston i go long dua bilong matmat.',
        47: 'Na Maria Magdala na Maria, mama bilong Joses, i lukim hap we ol i slipim Em.',
    },
    16: {
        1: '¶ Na taim sabat i pinis, Maria Magdala, na Maria, mama bilong Jems, na Salomi, i bin bringim ol switpela spais, inap long ol i ken kam na makim bodi bilong Em wantaim wel.',
        2: 'Na long moningtaim tru long namba wan de bilong wik, ol i kam long matmat long taim san i kam antap.',
        3: 'Na ol i toktok namel long ol yet, Husat bai tantanim dispela ston i go lusim dua bilong matmat long helpim yumi?',
        4: 'Na taim ol i lukluk, ol i luksave long wanpela i tantanim ston i go pinis. Long wanem, em i bikpela tru.',
        5: 'Na taim ol i go insait long matmat, ol i lukim wanpela yangpela man i sindaun long han sut sait, husat i werim klos long wanpela longpela waitpela klos. Na ol i pret.',
        6: 'Na em i tokim ol, No ken pret. Yupela i painim Jisas bilong Nasaret, husat ol i nilim long diwai kros. Em i kirap bek pinis. Em i no stap hia. Lukim ples we ol i bin slipim Em.',
        7: 'Tasol go long rot bilong yupela, tokim ol disaipel bilong Em na Pita long Em i go paslain long yupela long Galili. Long dispela hap yupela bai lukim Em, olsem Em i tokim yupela.',
        8: 'Na ol i go kwiktaim, na ranawe long matmat. Long wanem, ol i guria na ol i kirap nogut tru. Na tu ol i no tokim wanpela samting long wanpela man. Long wanem, ol i pret.',
        9: '¶ Nau taim Jisas i kirap bek pinis long moning tru bilong namba wan de bilong wik, Em i kamap ples klia long Maria Magdala pastaim, ausait long husat Em i bin rausim sevenpela spirit nogut.',
        10: 'Na em i go na tokim ol husat i bin stap wantaim Em, taim ol i soim sori na krai tru.',
        11: 'Na ol, taim ol i bin harim long Em i stap laip, na meri i bin lukim Em, ol i no bilip.',
        12: 'Bihain long dispela Em i kamap ples klia long tupela bilong ol na luk olsem narapela, taim ol i wokabaut, na go long hap i no gat planti man.',
        13: 'Na tupela i go na tokim ol arapela lain i stap yet. Na tu ol i no bilipim ol.',
        14: '¶ Bihain long en Em i kamap ples klia long dispela elevenpela taim ol i sindaun long kaikai, na givim sem long ol wantaim dispela pasin bilong i no gat bilip bilong ol na bikos bel bilong ol i hat tru, bilong wanem, ol i no bilipim ol husat i bin lukim Em bihain long Em i bin kirap bek.',
        15: 'Na Em i tokim ol, Yupela go long olgeta hap bilong dispela graun, na autim gutnius long olgeta wan wan samting God i wokim.',
        16: 'Em husat i bilip na kisim baptais, God bai kisim bek. Tasol em husat i no bilip bai lus olgeta long kot.',
        17: 'Na ol dispela mak bai bihainim ol husat i bilip. Long nem bilong Mi ol bai rausim ol spirit nogut. Ol bai toktok wantaim ol nupela tok ples.',
        18: 'Ol bai kisim ol snek i go antap. Na sapos ol i dringim wanpela samting bilong mekim man i dai, em bai i no inap bagarapim ol. Ol bai putim ol han antap long ol sikman, na ol bai kamap orait gen.',
        19: '¶ Olsem tasol nau bihain long Bikpela i bin toktok long ol, God i kisim Em i go antap long heven, na Em i sindaun long han sut bilong God.',
        20: 'Na ol i go ausait, na autim tok long olgeta wan wan hap, na Bikpela i wokim wantaim ol, na strongim dispela tok wantaim ol mak i bihainim. Amen.',
    },
}
